const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

function scoreColor(s) { return s >= 70 ? '#22c55e' : s >= 40 ? '#f59e0b' : '#ef4444'; }
function scoreLabel(s) { return s >= 70 ? 'Bon' : s >= 40 ? 'Moyen' : 'Critique'; }
function impactColor(i) { return i === 'Très élevé' ? '#ef4444' : i === 'Élevé' ? '#f59e0b' : '#22c55e'; }
function statusBadgeColor(s) { return s === 'up' ? '#22c55e' : s === 'down' ? '#ef4444' : '#f59e0b'; }
function statusLabel(s) { return s === 'up' ? 'UP' : s === 'down' ? 'DOWN' : 'LENT'; }
function relDate(d) { return new Date(d).toLocaleDateString('fr-FR'); }
function sanitizeNotes(raw) { return String(raw).replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim().slice(0,2000); }
function unread() { return STATE.notifications.filter(n => !n.read).length; }
function avgScore() { return STATE.audits.length ? Math.round(STATE.audits.reduce((a,b) => a+b.score, 0) / STATE.audits.length) : 0; }
function monitorsDown() { return STATE.monitors.filter(m => m.status === 'down').length; }
function saveMissions() {
  // Persistance backend uniquement — mutations gérées par FP_MISSIONS_API directement.
  // Pas de localStorage pour les données métier en production.
}
// ── Quick mission creator — used by inline buttons throughout the dashboard ──
window._fpMQ = async function(title, category, priority, navAfter) {
  if (!title) return;
  const ms = {
    id: 'qm_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    title: title,
    category: category || 'Optimisation',
    priority: priority || 'medium',
    status: 'todo',
    createdAt: new Date().toISOString(),
    steps: [],
  };
  if (!STATE.missions) STATE.missions = [];
  STATE.missions.unshift(ms);
  try {
    if (window.FP_MISSIONS_API && typeof FP_MISSIONS_API.create === 'function') {
      await FP_MISSIONS_API.create(ms);
    }
  } catch(e) {}
  showToast('success', 'Mission créée · ' + title.slice(0, 40));
  logActivityEvent('success', 'Mission créée : ' + title.slice(0, 60));
  if (navAfter) setTimeout(() => navigate('missions'), 600);
};
function logActivityEvent(type, label, metadata = {}) {
  fetch('/api/activity', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ type, label, metadata }) }).catch(() => {});
}
function saveCalendarEvents() { /* calendar events persisted via API only */ }
function saveSettings() {
  localStorage.setItem('fp-settings', JSON.stringify(STATE.settings));
  apiAction('PATCH', '/api/me/prefs', { settings: STATE.settings }).catch(() => {});
}
function saveChecklist() {
  apiAction('PATCH', '/api/me/prefs', { checklist: STATE.checklist }).catch(() => {});
}
function saveNotifs() { /* notifications persisted via API only */ }

