function openEmojiPicker(targetInputId, anchorEl) {
  // Remove any existing picker and its stale listener
  document.getElementById('fp-emoji-picker')?.remove();
  if (window._fpEmojiOutsideClose) {
    document.removeEventListener('click', window._fpEmojiOutsideClose);
    window._fpEmojiOutsideClose = null;
  }

  const pickerState = { cat: Object.keys(EMOJI_CATEGORIES)[0], q: '' };

  const picker = document.createElement('div');
  picker.id = 'fp-emoji-picker';

  const rect = anchorEl ? anchorEl.getBoundingClientRect() : { bottom: 200, left: 100, top: 180 };
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const pickerW = Math.min(330, vw - 16);
  const left = Math.max(8, Math.min(rect.left, vw - pickerW - 8));
  const spaceBelow = vh - rect.bottom - 10;
  const top = spaceBelow >= 360 ? rect.bottom + 6 : Math.max(8, rect.top - 366);
  picker.style.cssText = `position:fixed;z-index:99999;top:${top}px;left:${left}px;width:${pickerW}px`;

  function closePicker() {
    picker.remove();
    if (window._fpEmojiOutsideClose) {
      document.removeEventListener('click', window._fpEmojiOutsideClose);
      window._fpEmojiOutsideClose = null;
    }
  }

  function renderPicker() {
    const cats = Object.keys(EMOJI_CATEGORIES);
    const emojis = pickerState.q
      ? Object.values(EMOJI_CATEGORIES).flat().filter(e => e.includes(pickerState.q))
      : EMOJI_CATEGORIES[pickerState.cat] || [];
    picker.innerHTML = `
      <input id="fp-emoji-search" placeholder="Rechercher…" value="${pickerState.q}" autocomplete="off"/>
      <div class="fp-emoji-cats">
        ${cats.map(k => `<button class="fp-emoji-cat-btn${k===pickerState.cat&&!pickerState.q?' active':''}" data-cat="${k}">${k}</button>`).join('')}
      </div>
      <div class="fp-emoji-grid">
        ${emojis.map(e => `<div class="fp-emoji-item" data-e="${e}">${e}</div>`).join('')}
      </div>
    `;
    picker.querySelector('#fp-emoji-search').addEventListener('input', function() {
      pickerState.q = this.value;
      renderPicker();
      picker.querySelector('#fp-emoji-search').focus();
    });
    picker.querySelectorAll('.fp-emoji-cat-btn').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      pickerState.cat = btn.dataset.cat; pickerState.q = ''; renderPicker();
    }));
    picker.querySelectorAll('.fp-emoji-item').forEach(item => item.addEventListener('click', e => {
      e.stopPropagation();
      const inp = targetInputId ? document.getElementById(targetInputId) : null;
      if (inp) {
        const pos = (inp.selectionStart != null ? inp.selectionStart : inp.value.length);
        inp.value = inp.value.slice(0, pos) + item.dataset.e + inp.value.slice(pos);
        inp.focus();
        try { inp.setSelectionRange(pos + item.dataset.e.length, pos + item.dataset.e.length); } catch(_) {}
      }
      closePicker();
    }));
  }
  renderPicker();
  document.body.appendChild(picker);
  setTimeout(() => {
    window._fpEmojiOutsideClose = function outsideClose(e) {
      if (!picker.contains(e.target) && !e.target.closest('[id^="fp-emoji-trigger"]')) {
        closePicker();
      }
    };
    document.addEventListener('click', window._fpEmojiOutsideClose);
  }, 20);
}

// ─────────────────────────────────────────────────────────────────
// ACTIVITY FEED PANEL
// ─────────────────────────────────────────────────────────────────
const ACTIVITY_TYPE_CONFIG = {
  audit:   { label:'Audit',   color:'#2563EB', bg:'rgba(37,99,235,0.12)' },
  monitor: { label:'Monitor', color:'#22c55e', bg:'rgba(34,197,94,0.12)' },
  report:  { label:'Rapport', color:'#f59e0b', bg:'rgba(245,158,11,0.12)' },
  alert:   { label:'Alerte',  color:'#ef4444', bg:'rgba(239,68,68,0.12)' },
  team:    { label:'Équipe',  color:'#8b5cf6', bg:'rgba(139,92,246,0.12)' },
};
const AVATAR_COLORS = ['#2563EB','#22c55e','#f59e0b','#8b5cf6','#ef4444','#06b6d4'];

function getAvatarColor(name) {
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
}

function getInitials(name) {
  return (name || '?').split(' ').map(w => w[0]).slice(0, 2).join('').toUpperCase();
}

function relTimeActivity(dateStr) {
  const diff = Math.floor((Date.now() - new Date(dateStr).getTime()) / 1000);
  if (diff < 60) return 'À l\'instant';
  if (diff < 3600) return `Il y a ${Math.floor(diff/60)} min`;
  if (diff < 86400) return `Il y a ${Math.floor(diff/3600)}h`;
  if (diff < 172800) return 'Hier';
  return new Date(dateStr).toLocaleDateString('fr-FR', { day:'2-digit', month:'short' });
}

function countActivityUnread() {
  return STATE.activityEvents.filter(e => new Date(e.createdAt).getTime() > STATE.activityLastSeen).length;
}

function updateActivityBadge() {
  const badge = $('#fp-activity-badge');
  if (!badge) return;
  const n = countActivityUnread();
  if (n > 0) {
    badge.removeAttribute('hidden');
    badge.textContent = n > 9 ? '9+' : n;
  } else {
    badge.setAttribute('hidden', '');
  }
}

function renderActivityList() {
  const list = $('#fp-activity-list');
  if (!list) return;
  const filter = STATE.activityFilter;
  const events = filter === 'all'
    ? STATE.activityEvents
    : STATE.activityEvents.filter(e => e.type === filter);

  if (events.length === 0) {
    list.innerHTML = `<div class="fp-activity-empty">
      <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
      <div>Aucune activité pour ce filtre</div>
    </div>`;
    return;
  }

  const lastSeen = STATE.activityLastSeen;
  list.innerHTML = events.map(e => {
    const cfg = ACTIVITY_TYPE_CONFIG[e.type] || ACTIVITY_TYPE_CONFIG.audit;
    const avatarColor = getAvatarColor(e.userName || 'U');
    const isNew = new Date(e.createdAt).getTime() > lastSeen;
    return `
      <div class="fp-activity-item${isNew ? ' fp-activity-new' : ''}">
        <div class="fp-activity-avatar" style="background:${avatarColor}20;color:${avatarColor}">
          ${getInitials(e.userName)}
        </div>
        <div class="fp-activity-body">
          <div class="fp-activity-panel-label">${escHtml(e.label)}</div>
          <div class="fp-activity-meta">
            <span class="fp-activity-user-name">${escHtml(e.userName || 'Équipe')}</span>
            <span class="fp-activity-time-rel">${relTimeActivity(e.createdAt)}</span>
            <span class="fp-activity-type-chip" style="background:${cfg.bg};color:${cfg.color}">${cfg.label}</span>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function openActivityPanel() {
  const panel = $('#fp-activity-panel');
  const overlay = $('#fp-activity-overlay');
  if (!panel || !overlay) return;
  panel.removeAttribute('hidden');
  overlay.removeAttribute('hidden');
  requestAnimationFrame(() => {
    panel.classList.add('visible');
    overlay.classList.add('visible');
  });
  STATE.activityPanelOpen = true;
  // Mark as seen — update timestamp
  STATE.activityLastSeen = Date.now();
  localStorage.setItem('fp-activity-last-seen', String(STATE.activityLastSeen));
  updateActivityBadge();
  renderActivityList();
}

function closeActivityPanel() {
  const panel = $('#fp-activity-panel');
  const overlay = $('#fp-activity-overlay');
  if (!panel || !overlay) return;
  panel.classList.remove('visible');
  overlay.classList.remove('visible');
  STATE.activityPanelOpen = false;
  setTimeout(() => {
    panel.setAttribute('hidden', '');
    overlay.setAttribute('hidden', '');
  }, 320);
}

function bindActivityPanel() {
  $('#fp-activity-btn')?.addEventListener('click', e => {
    e.stopPropagation();
    if (STATE.activityPanelOpen) closeActivityPanel();
    else openActivityPanel();
  });

  $('#fp-activity-close')?.addEventListener('click', closeActivityPanel);
  $('#fp-activity-overlay')?.addEventListener('click', closeActivityPanel);

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && STATE.activityPanelOpen) closeActivityPanel();
  });

  const filters = $('#fp-activity-filters');
  if (filters) {
    filters.addEventListener('click', e => {
      const btn = e.target.closest('.fp-activity-filter');
      if (!btn) return;
      $$('.fp-activity-filter', filters).forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      STATE.activityFilter = btn.dataset.filter || 'all';
      renderActivityList();
    });
  }

  // Push notification toggle button in the activity panel header
  $('#fp-push-toggle-btn')?.addEventListener('click', () => togglePushNotifications());

  // Sync initial push toggle UI state
  updatePushToggleUI();
}

function pushActivityEvent(event) {
  // Prepend new event to STATE
  STATE.activityEvents.unshift(event);
  if (STATE.activityEvents.length > 50) STATE.activityEvents.pop();

  // Flash badge
  const badge = $('#fp-activity-badge');
  if (!STATE.activityPanelOpen) {
    updateActivityBadge();
    if (badge) {
      badge.classList.remove('fp-badge-pulse');
      requestAnimationFrame(() => badge.classList.add('fp-badge-pulse'));
    }
  }

  // Fire browser push notification if tab is hidden
  if (document.hidden) {
    firePushNotification(event);
  }

  // If panel is open, re-render
  if (STATE.activityPanelOpen) renderActivityList();
}

// ─────────────────────────────────────────────────────────────────
// BROWSER PUSH NOTIFICATIONS
// ─────────────────────────────────────────────────────────────────

function firePushNotification(event) {
  if (!STATE.pushNotifEnabled) return;
  if (!('Notification' in window)) return;
  if (Notification.permission !== 'granted') return;

  const title = event.userName
    ? `${event.userName} — Flowpoint`
    : 'Flowpoint';
  const body = event.label
    ? event.label.replace(/<[^>]*>/g, '')
    : 'Nouvelle activité équipe';

  try {
    const notif = new Notification(title, {
      body,
      icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="%232563EB"/><path d="M18.5 4L8 17.5h8.5L14.5 28 24 14.5h-8.5L18.5 4z" fill="white"/></svg>',
      tag: 'fp-activity',
      renotify: true,
    });
    notif.onclick = () => {
      window.focus();
      notif.close();
      openActivityPanel();
    };
  } catch(e) {}
}

async function requestPushPermission() {
  if (!('Notification' in window)) {
    showToast('warning', 'Votre navigateur ne supporte pas les notifications push');
    return false;
  }
  if (Notification.permission === 'granted') return true;
  if (Notification.permission === 'denied') {
    showToast('warning', 'Notifications bloquées — autorisez-les dans les réglages du navigateur');
    return false;
  }
  const result = await Notification.requestPermission();
  return result === 'granted';
}

async function togglePushNotifications() {
  if (STATE.pushNotifEnabled) {
    STATE.pushNotifEnabled = false;
    localStorage.setItem('fp-push-notif', '0');
    showToast('info', 'Notifications push désactivées');
    updatePushToggleUI();
  } else {
    const granted = await requestPushPermission();
    if (granted) {
      STATE.pushNotifEnabled = true;
      localStorage.setItem('fp-push-notif', '1');
      showToast('success', 'Notifications push activées — vous serez alerté même onglet réduit');
      updatePushToggleUI();
    }
  }
}

function updatePushToggleUI() {
  // Activity panel toggle button
  const btn = $('#fp-push-toggle-btn');
  if (btn) {
    const on = STATE.pushNotifEnabled;
    btn.setAttribute('aria-pressed', String(on));
    btn.setAttribute('title', on ? 'Désactiver les notifications push' : 'Activer les notifications push');
    btn.classList.toggle('fp-push-toggle-active', on);
  }
  // Settings toggle (if visible)
  const settingsToggle = $('#fp-settings-push-toggle');
  if (settingsToggle) {
    settingsToggle.classList.toggle('on', STATE.pushNotifEnabled);
    settingsToggle.setAttribute('aria-pressed', String(STATE.pushNotifEnabled));
  }
}

