const FAB_ACTIONS = [
  { icon:'message-circle', label:'Chat IA',              color:'#8b5cf6', action:'open-chat'  },
  { icon:'layout',         label:'Disposition',           color:'#06b6d4', action:'layout-edit'},
  { icon:'search',         label:'Nouvel audit',         color:'#2563EB', action:'new-audit'  },
  { icon:'activity',       label:'Nouveau monitor',      color:'#22c55e', action:'new-monitor'},
  { icon:'rocket',         label:'Nouvelle mission',     color:'#8b5cf6', action:'new-mission'},
  { icon:'globe',          label:'Nouvelle grille géo',  color:'#22c55e', action:'new-geo'    },
  { icon:'file',           label:'Générer rapport PDF',  color:'#f59e0b', action:'new-report' },
  { icon:'download',       label:'Exporter les données', color:'#06b6d4', action:'export-data'},
];

function renderFAB() {
  const actionsEl = $('#fp-fab-actions');
  if (!actionsEl) return;
  if (!STATE.fabOpen) { actionsEl.innerHTML = ''; return; }

  // Vertical list above FAB, newest at bottom
  actionsEl.innerHTML = FAB_ACTIONS.map((a, i) => `
    <div class="fp-fab-action-item" style="animation-delay:${(FAB_ACTIONS.length - 1 - i) * 0.05}s">
      <span class="fp-fab-action-label">${escHtml(a.label)}</span>
      <button class="fp-fab-action-btn" data-fab-action="${a.action}"
        style="background:rgba(37,99,235,0.12);border-color:rgba(37,99,235,0.3);"
        title="${escHtml(a.label)}">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--fp-accent)" stroke-width="2">${svgIcon(a.icon).match(/<svg[^>]*>([\s\S]*)<\/svg>/)?.[1]||''}</svg>
      </button>
    </div>`).join('');

  actionsEl.querySelectorAll('[data-fab-action]').forEach(btn => {
    btn.addEventListener('click', e => { e.stopPropagation(); handleFABAction(btn.dataset.fabAction); closeFAB(); });
  });
}

function toggleFAB() {
  if (STATE.fabOpen) { closeFAB(); return; }
  STATE.fabOpen = true;
  const fab = $('#fp-fab');
  const backdrop = $('#fp-fab-backdrop');
  fab.classList.add('open');
  fab.setAttribute('aria-expanded', 'true');
  if (backdrop) backdrop.classList.add('show');
  renderFAB();
}

function closeFAB() {
  STATE.fabOpen = false;
  const fab = $('#fp-fab');
  if (fab) { fab.classList.remove('open'); fab.setAttribute('aria-expanded','false'); }
  const backdrop = $('#fp-fab-backdrop');
  if (backdrop) backdrop.classList.remove('show');
  const items = document.querySelectorAll('.fp-fab-action-item');
  if (items.length) {
    const n = items.length;
    items.forEach((item, i) => {
      item.style.setProperty('--fab-close-delay', `${i * 0.05}s`);
      item.classList.add('closing');
    });
    setTimeout(() => renderFAB(), 260 + n * 55);
  } else {
    renderFAB();
  }
}

function handleFABAction(action) {
  if (action === 'new-audit')   { openFloatPanel('Nouvel audit', renderNewAuditPanel()); setupNewAuditPanel(); }
  if (action === 'new-monitor') { openFloatPanel('Nouveau monitor', renderNewMonitorPanel()); setupNewMonitorPanel(); }
  if (action === 'new-mission') { openFloatPanel('Nouvelle mission', renderNewMissionPanel()); setupNewMissionPanel(); }
  if (action === 'new-report')  { openFloatPanel('Générer un rapport PDF', renderNewReportPanel()); setupNewReportPanel(); }
  if (action === 'export-data') { openFloatPanel('Exporter les données', renderExportPanel()); setupExportPanel(); }
  if (action === 'new-geo')     { navigate('local-seo'); setTimeout(()=>{ window._mapsTab='grid'; render(STATE.currentSection); window._showCreateHeatmapModal?.(); }, 300); }
  if (action === 'open-chat')   { document.querySelector('#fp-ai-chat-toggle, .fp-chat-fab')?.click(); showToast('info','Chat IA ouvert'); }
  if (action === 'layout-edit') { toggleLayoutEditMode(); }
}

// ─────────────────────────────────────────────────────────────────
// LAYOUT EDIT MODE — redimensionner / déplacer les cards
// ─────────────────────────────────────────────────────────────────
function toggleLayoutEditMode() {
  STATE.layoutEditMode = !STATE.layoutEditMode;
  document.body.classList.toggle('fp-layout-edit', STATE.layoutEditMode);

  if (STATE.layoutEditMode) {
    $$('.fp-card').forEach(card => {
      if (card.querySelector('.fp-card-edit-toolbar')) return;
      const tb = document.createElement('div');
      tb.className = 'fp-card-edit-toolbar';
      tb.innerHTML =
        '<button class="fp-cedit-btn" onclick="fpCardMove(this,\'left\')" title="Déplacer à gauche">&#8592;</button>' +
        '<button class="fp-cedit-btn" onclick="fpCardMove(this,\'right\')" title="Déplacer à droite">&#8594;</button>' +
        '<button class="fp-cedit-btn" onclick="fpCardMove(this,\'up\')" title="Déplacer en haut">&#8593;</button>' +
        '<button class="fp-cedit-btn" onclick="fpCardMove(this,\'down\')" title="Déplacer en bas">&#8595;</button>' +
        '<button class="fp-cedit-btn fp-cedit-wide" onclick="fpCardToggleWide(this)" title="Agrandir / réduire">&#8596;</button>';
      card.style.position = 'relative';
      card.appendChild(tb);
    });
    let banner = document.getElementById('fp-layout-edit-banner');
    if (!banner) {
      banner = document.createElement('div');
      banner.id = 'fp-layout-edit-banner';
      banner.className = 'fp-layout-edit-banner';
      document.body.appendChild(banner);
    }
    banner.innerHTML = '&#128210; Mode mise en page actif &nbsp;<button onclick="toggleLayoutEditMode()" class="fp-cedit-done">&#10003; Terminer</button>';
    banner.style.display = 'flex';
    showToast('info', 'Cliquez sur ← → ↑ ↓ pour déplacer, ↔ pour agrandir');
  } else {
    $$('.fp-card-edit-toolbar').forEach(tb => tb.remove());
    const banner = document.getElementById('fp-layout-edit-banner');
    if (banner) banner.style.display = 'none';
    showToast('success', 'Mise en page enregistrée');
  }
}

function fpCardMove(btn, dir) {
  const card = btn.closest('.fp-card');
  if (!card) return;
  const parent = card.parentElement;
  if (!parent) return;
  const siblings = Array.from(parent.children).filter(c => c.classList.contains('fp-card'));
  const idx = siblings.indexOf(card);
  if ((dir === 'left' || dir === 'up') && idx > 0) {
    parent.insertBefore(card, siblings[idx - 1]);
    showToast('success', 'Carte déplacée');
  } else if ((dir === 'right' || dir === 'down') && idx < siblings.length - 1) {
    parent.insertBefore(siblings[idx + 1], card);
    showToast('success', 'Carte déplacée');
  }
  _fpSaveLayout();
}

function fpCardToggleWide(btn) {
  const card = btn.closest('.fp-card');
  if (!card) return;
  const isWide = card.style.gridColumn === 'span 2';
  card.style.gridColumn = isWide ? '' : 'span 2';
  btn.title = isWide ? 'Agrandir' : 'Réduire';
  btn.innerHTML = isWide ? '&#8596;' : '&#8596;&#8596;';
  _fpSaveLayout();
}

// ─── LAYOUT PERSISTENCE ────────────────────────────────────────
const _FP_LAYOUT_KEY = 'fp_layout_v2';

function _fpCardHash(card) {
  const clone = card.cloneNode(true);
  clone.querySelector('.fp-card-edit-toolbar')?.remove();
  const h = clone.querySelector('.fp-card-title, .fp-section-title, h2, h3, h1, [class*="title"]');
  const text = h ? h.textContent.trim() : clone.textContent.trim().slice(0, 60);
  return text.replace(/\s+/g, ' ').trim().slice(0, 50);
}

function _fpParentKey(el) {
  const cls = Array.from(el.classList).filter(c => c.startsWith('fp-')).sort().join('-');
  const parent = el.parentElement;
  if (!parent) return cls || 'root';
  const idx = Array.from(parent.children).indexOf(el);
  return (cls || 'el') + '_' + idx;
}

function _fpSaveLayout() {
  try {
    const saved = JSON.parse(localStorage.getItem(_FP_LAYOUT_KEY) || '{}');
    const routeData = {};
    const seenParents = new Set();
    $$('.fp-card').forEach(card => {
      const parent = card.parentElement;
      if (!parent) return;
      seenParents.add(parent);
    });
    seenParents.forEach(parent => {
      const key = _fpParentKey(parent);
      const cards = Array.from(parent.children).filter(c => c.classList.contains('fp-card'));
      routeData[key] = cards.map(c => ({
        hash: _fpCardHash(c),
        wide: c.style.gridColumn === 'span 2'
      }));
    });
    saved[STATE.route] = routeData;
    localStorage.setItem(_FP_LAYOUT_KEY, JSON.stringify(saved));
  } catch(e) {}
}

function _fpApplyLayout() {
  try {
    const saved = JSON.parse(localStorage.getItem(_FP_LAYOUT_KEY) || '{}');
    const routeData = saved[STATE.route];
    if (!routeData) return;
    const seenParents = new Set();
    $$('.fp-card').forEach(card => { if (card.parentElement) seenParents.add(card.parentElement); });
    seenParents.forEach(parent => {
      const key = _fpParentKey(parent);
      const savedOrder = routeData[key];
      if (!savedOrder || !savedOrder.length) return;
      const currentCards = Array.from(parent.children).filter(c => c.classList.contains('fp-card'));
      if (currentCards.length !== savedOrder.length) return;
      const hashToCard = new Map();
      currentCards.forEach(c => { const h = _fpCardHash(c); if (!hashToCard.has(h)) hashToCard.set(h, c); });
      const ordered = savedOrder.map(({hash}) => hashToCard.get(hash));
      if (ordered.some(c => !c)) return;
      ordered.forEach(card => parent.appendChild(card));
      savedOrder.forEach(({hash, wide}, i) => {
        const card = ordered[i];
        if (card) card.style.gridColumn = wide ? 'span 2' : '';
      });
    });
  } catch(e) {}
}

// ─────────────────────────────────────────────────────────────────
// NOTIFICATIONS
// ─────────────────────────────────────────────────────────────────
// ─── GOOGLE MAPS ──────────────────────────────────────────────
let _gmapsKey = null;
let _gmapsLoading = false;

async function _fetchGmapsKey() {
  if (_gmapsKey !== null) return _gmapsKey;
  try {
    const r = await fetch('/api/maps/config', { credentials: 'include' });
    if (r.ok) { const d = await r.json(); _gmapsKey = d.apiKey || ''; }
    else { _gmapsKey = ''; }
  } catch (_) { _gmapsKey = ''; }
  return _gmapsKey;
}

function loadGoogleMaps(cb) {
  if (typeof google !== 'undefined' && google.maps) { cb(); return; }
  if (_gmapsLoading) {
    const t = setInterval(() => { if (typeof google !== 'undefined' && google.maps) { clearInterval(t); cb(); } }, 150);
    return;
  }
  _gmapsLoading = true;
  _fetchGmapsKey().then(key => {
    if (!key) {
      _gmapsLoading = false;
      console.warn('[FlowPoint] Google Maps API key not configured — add GOOGLE_MAPS_API_KEY to environment secrets');
      return;
    }
    window.__gmapsCb = () => { _gmapsLoading = false; cb(); };
    const s = document.createElement('script');
    s.src = `https://maps.googleapis.com/maps/api/js?key=${key}&callback=__gmapsCb`;
    s.async = true;
    document.head.appendChild(s);
  });
}

function initLocalSEOMap() {
  const el = document.getElementById('fp-gmap');
  if (!el) return;
  loadGoogleMaps(() => {
    const mapEl = document.getElementById('fp-gmap');
    if (!mapEl || mapEl._mapInited) return;
    mapEl._mapInited = true;
    const isLight = document.documentElement.dataset.theme === 'light';
    const darkStyles = [
      { elementType:'geometry', stylers:[{color:'#0d1525'}] },
      { elementType:'labels.text.stroke', stylers:[{color:'#0a0f1e'}] },
      { elementType:'labels.text.fill', stylers:[{color:'#7a94b8'}] },
      { featureType:'road', elementType:'geometry', stylers:[{color:'#1a2a42'}] },
      { featureType:'road.highway', elementType:'geometry', stylers:[{color:'#1e3a8a'}] },
      { featureType:'water', elementType:'geometry', stylers:[{color:'#050810'}] },
      { featureType:'poi', elementType:'geometry', stylers:[{color:'#0f1f35'}] },
      { featureType:'transit', elementType:'geometry', stylers:[{color:'#0f1f35'}] },
      { featureType:'landscape', elementType:'geometry', stylers:[{color:'#0a1525'}] },
      { featureType:'administrative', elementType:'geometry.stroke', stylers:[{color:'#1d3055'}] },
    ];
    const center = { lat:48.8566, lng:2.3522 };
    const map = new google.maps.Map(mapEl, {
      zoom:14, center,
      styles: isLight ? [] : darkStyles,
      mapTypeControl:false, streetViewControl:false, fullscreenControl:true,
      gestureHandling:'cooperative',
    });
    STATE._gmap = map;
    STATE._gmapDark = darkStyles;
    // Business marker
    const bm = new google.maps.Marker({
      position:center, map, zIndex:10, title:'Votre établissement',
      icon:{ path:google.maps.SymbolPath.CIRCLE, scale:13, fillColor:'#2563EB', fillOpacity:1, strokeColor:'#fff', strokeWeight:3 }
    });
    const bIW = new google.maps.InfoWindow({ content:`<div style="font-family:Inter,sans-serif;padding:10px;min-width:160px"><strong>📍 Votre établissement</strong><div style="margin-top:6px;font-size:12px;color:#475569">Score SEO&nbsp;<strong style="color:#2563EB">74/100</strong></div><div style="font-size:12px;color:#22c55e">↑ +8% ce mois · Top 5 Google</div></div>` });
    bm.addListener('click', () => bIW.open(map, bm));
    new google.maps.Circle({ map, center, radius:1200, fillColor:'#2563EB', fillOpacity:0.06, strokeColor:'#2563EB', strokeOpacity:0.3, strokeWeight:2 });
    // Competitors
    (STATE.competitors && STATE.competitors.length > 0
      ? STATE.competitors.slice(0,5).map((c,i) => ({
          name: c.name || `Concurrent ${String.fromCharCode(65+i)}`,
          lat: center.lat + (i%2===0?1:-1)*0.005*(Math.floor(i/2)+1),
          lng: center.lng + (i%2===0?-1:1)*0.007*(Math.floor(i/2)+1),
          score: Math.min(100,Math.round((c.domainRating||0)*1.5)),
          reviews: c.reviews||0,
          threat: (c.domainRating||0)>50?'Élevée':(c.domainRating||0)>30?'Modérée':'Faible',
          color: (c.domainRating||0)>50?'#ef4444':(c.domainRating||0)>30?'#f59e0b':'#22c55e',
        }))
      : PREVIEW_MODE ? [
          { name:'Concurrent A', lat:48.863, lng:2.365, score:78, reviews:127, threat:'Élevée',  color:'#ef4444' },
          { name:'Concurrent B', lat:48.849, lng:2.338, score:65, reviews:89,  threat:'Modérée', color:'#f59e0b' },
          { name:'Concurrent C', lat:48.870, lng:2.341, score:82, reviews:203, threat:'Élevée',  color:'#ef4444' },
          { name:'Concurrent D', lat:48.843, lng:2.359, score:58, reviews:45,  threat:'Faible',  color:'#22c55e' },
          { name:'Concurrent E', lat:48.855, lng:2.372, score:71, reviews:112, threat:'Modérée', color:'#f59e0b' },
        ] : []
    ).forEach(c => {
      const mk = new google.maps.Marker({
        position:{lat:c.lat,lng:c.lng}, map, title:c.name,
        icon:{ path:google.maps.SymbolPath.CIRCLE, scale:9, fillColor:c.color, fillOpacity:0.9, strokeColor:'#fff', strokeWeight:2 }
      });
      const iw = new google.maps.InfoWindow({ content:`<div style="font-family:Inter,sans-serif;padding:10px;min-width:190px"><strong style="font-size:13px">${c.name}</strong><div style="display:flex;gap:16px;margin-top:8px"><div style="text-align:center"><div style="font-size:18px;font-weight:700">${c.score}</div><div style="font-size:10px;color:#94a3b8">Score SEO</div></div><div style="text-align:center"><div style="font-size:18px;font-weight:700">${c.reviews}</div><div style="font-size:10px;color:#94a3b8">Avis Google</div></div></div><div style="margin-top:8px;padding:3px 8px;border-radius:4px;font-size:11px;font-weight:600;display:inline-block;background:${c.color}22;color:${c.color}">Menace: ${c.threat}</div></div>` });
      mk.addListener('click', () => iw.open(map, mk));
    });
  });
}

