function getChMsgs() {
  if (!STATE.channelMessages) STATE.channelMessages = PREVIEW_MODE ? JSON.parse(JSON.stringify(CHANNEL_MSGS_DEFAULT)) : {general:[],seo:[],rapports:[],support:[]};
  return STATE.channelMessages[STATE.msgChannel || 'general'] || [];
}

function getMsgUnreadTotal() {
  if (!STATE.channelMessages) STATE.channelMessages = PREVIEW_MODE ? JSON.parse(JSON.stringify(CHANNEL_MSGS_DEFAULT)) : {general:[],seo:[],rapports:[],support:[]};
  return Object.values(STATE.channelMessages).flat().filter(m => !m.read && !m.self).length;
}

function renderMsgDropdown() {
  const msgs = getChMsgs();
  const ch = STATE.msgChannel || 'general';
  const attach = STATE.msgAttachment;
  if (!STATE.channelMessages) STATE.channelMessages = PREVIEW_MODE ? JSON.parse(JSON.stringify(CHANNEL_MSGS_DEFAULT)) : {general:[],seo:[],rapports:[],support:[]};

  return `
  <div class="fp-msg-header">
    <span class="fp-notif-title">Messages</span>
    <button class="fp-notif-mark-all" id="fp-msg-mark-all">Tout lu</button>
  </div>
  <div class="fp-msg-channels">
    ${MSG_CHANNELS.map(c => {
      const u = (STATE.channelMessages[c.id]||[]).filter(m=>!m.read&&!m.self).length;
      return `<button class="fp-msg-channel-btn${c.id===ch?' active':''}" data-channel="${c.id}">${escHtml(c.label)}${u>0?`<span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--fp-accent);flex-shrink:0"></span>`:''}
      </button>`;
    }).join('')}
  </div>
  <div class="fp-msg-list" id="fp-msg-list">
    ${msgs.length===0 ? `<div style="text-align:center;padding:28px 16px;color:var(--fp-text-faint);font-size:12px">Aucun message dans ce canal</div>` :
      msgs.map(m => {
        const bg = m.self ? 'rgba(37,99,235,0.25)' : 'rgba(139,92,246,0.25)';
        const col = m.self ? '#2563EB' : '#8b5cf6';
        return `<div class="fp-msg-item${m.read?'':' unread'}${m.self?' self':''}" style="${m.self?'flex-direction:row-reverse':''};display:flex;align-items:flex-end;gap:7px">
          <div class="fp-msg-avatar" style="background:${bg};color:${col};flex-shrink:0">${escHtml(m.from[0])}</div>
          <div class="fp-msg-body" style="${m.self?'align-items:flex-end':''};display:flex;flex-direction:column">
            <div style="display:flex;align-items:baseline;gap:6px;margin-bottom:2px;${m.self?'flex-direction:row-reverse':''}">
              <div class="fp-msg-from" style="${m.self?'color:#2563EB':''}">${m.self?'Vous':escHtml(m.from)}</div>
              <div class="fp-msg-time">${escHtml(m.time)}</div>
            </div>
            <div class="fp-msg-text" style="border-radius:${m.self?'12px 4px 12px 12px':'4px 12px 12px 12px'};background:${m.self?'rgba(37,99,235,0.15)':''};border-color:${m.self?'rgba(37,99,235,0.25)':'rgba(255,255,255,0.06)'};color:${m.self?'#c7d9ff':''}">${escHtml(m.text)}</div>
          </div>
        </div>`;
      }).join('')}
  </div>
  ${attach ? `<div class="fp-msg-attachment">
    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"/></svg>
    <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(attach)}</span>
    <button class="fp-msg-attachment-remove" id="fp-msg-rm-attach"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>` : ''}
  <div class="fp-msg-compose">
    <input type="file" id="fp-msg-file" style="display:none" accept="*/*"/>
    <button class="fp-msg-upload-btn" id="fp-msg-upload" title="Joindre un fichier">
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"/></svg>
    </button>
    <input id="fp-msg-input" class="fp-input" placeholder="Message #${escHtml(ch)}…" style="flex:1;font-size:12px;height:30px;padding:5px 10px"/>
    <button id="fp-msg-send" class="fp-btn fp-btn-primary fp-btn-sm" style="height:30px;padding:0 11px;flex-shrink:0">
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
    </button>
  </div>`;
}

function bindMsgPanel(dd) {
  if (!STATE.channelMessages) STATE.channelMessages = PREVIEW_MODE ? JSON.parse(JSON.stringify(CHANNEL_MSGS_DEFAULT)) : {general:[],seo:[],rapports:[],support:[]};

  const refreshBadge = () => {
    const u = getMsgUnreadTotal();
    const b = $('#fp-msg-badge');
    if (b) { u > 0 ? (b.removeAttribute('hidden'), b.textContent = u) : b.setAttribute('hidden',''); }
  };
  refreshBadge();

  dd.querySelectorAll('.fp-msg-channel-btn').forEach(btn => {
    btn.addEventListener('click', e => { e.stopPropagation(); STATE.msgChannel = btn.dataset.channel; dd.innerHTML = renderMsgDropdown(); bindMsgPanel(dd); });
  });

  dd.querySelector('#fp-msg-mark-all')?.addEventListener('click', e => {
    e.stopPropagation();
    Object.values(STATE.channelMessages).flat().forEach(m => m.read = true);
    dd.innerHTML = renderMsgDropdown(); bindMsgPanel(dd); refreshBadge();
  });

  const fileInput = dd.querySelector('#fp-msg-file');
  dd.querySelector('#fp-msg-upload')?.addEventListener('click', e => { e.stopPropagation(); fileInput?.click(); });
  fileInput?.addEventListener('change', e => {
    const f = e.target.files[0]; if (f) { STATE.msgAttachment = f.name; dd.innerHTML = renderMsgDropdown(); bindMsgPanel(dd); }
  });

  dd.querySelector('#fp-msg-rm-attach')?.addEventListener('click', e => {
    e.stopPropagation(); STATE.msgAttachment = null; dd.innerHTML = renderMsgDropdown(); bindMsgPanel(dd);
  });

  const input = dd.querySelector('#fp-msg-input');
  const send  = dd.querySelector('#fp-msg-send');

  const doSend = e => {
    if (e) e.stopPropagation();
    const val = input?.value?.trim();
    if (!val && !STATE.msgAttachment) return;
    const ch = STATE.msgChannel || 'general';
    if (!STATE.channelMessages[ch]) STATE.channelMessages[ch] = [];
    const msgObj = {
      from: STATE.me?.firstName || 'Vous',
      text: val || `📎 ${STATE.msgAttachment}`,
      time: 'À l\'instant', read: true, self: true,
    };
    STATE.channelMessages[ch].push(msgObj);
    if (input) input.value = '';
    STATE.msgAttachment = null;
    dd.innerHTML = renderMsgDropdown();
    bindMsgPanel(dd);
    const list = dd.querySelector('#fp-msg-list');
    if (list) list.scrollTop = list.scrollHeight;
    // Persistance backend (best-effort)
    if (val && typeof window.FP_CHAT_API !== 'undefined') {
      window.FP_CHAT_API.send(ch, val).catch(() => {});
    }
  };

  send?.addEventListener('click', doSend);
  input?.addEventListener('keydown', ke => { if (ke.key === 'Enter' && !ke.shiftKey) { ke.preventDefault(); doSend(); } });
  input?.focus();
}

function renderNotifications() {
  const badge = $('#fp-notif-badge');
  const u = unread();
  if (badge) { badge[u > 0 ? 'removeAttribute' : 'setAttribute']('hidden', ''); badge.textContent = u; }

  const dropdown = $('#fp-notif-dropdown');
  if (!dropdown) return;
  const typeColors = { error:'#ef4444', success:'#22c55e', warning:'#f59e0b', info:'#2563EB' };
  dropdown.innerHTML = `
    <div class="fp-notif-header">
      <span class="fp-notif-title">Notifications</span>
      <button class="fp-notif-mark-all" id="fp-notif-mark-all">Tout marquer lu</button>
    </div>
    ${STATE.notifications.map(n => `
      <div class="fp-notif-item${n.read ? '' : ' unread'}">
        <div class="fp-notif-dot" style="background:${typeColors[n.type]||'#2563EB'}"></div>
        <div class="fp-notif-body">
          <div class="fp-notif-item-title">${n.title}</div>
          <div class="fp-notif-item-desc">${n.desc}</div>
          <div class="fp-notif-item-time">Il y a ${n.time}</div>
        </div>
      </div>
    `).join('')}
  `;
  dropdown.querySelector('#fp-notif-mark-all')?.addEventListener('click', () => {
    STATE.notifications = STATE.notifications.map(n => ({ ...n, read: true }));
    saveNotifs();
    renderNotifications();
    showToast('success', 'Toutes les notifications marquées lues');
  });
}

