function renderSidebarStatus() {
  const me = STATE.me;
  if (!me) return;
  const down = monitorsDown();

  // Status dot & text
  const dot = $('#global-status-dot');
  const txt = $('#global-status-text');
  if (dot) { dot.className = 'fp-status-dot' + (down > 0 ? ' down' : ''); }
  if (txt) { txt.className = 'fp-status-text' + (down > 0 ? ' down' : ''); txt.textContent = down > 0 ? `${down} monitor DOWN` : 'Tous les systèmes OK'; }

  // Usage bars
  const usageEl = $('#sidebar-usage');
  if (usageEl) {
    const _usg    = me.usage   || {};
    const _auditU = _usg.audit   || { used: 0, limit: 100 };
    const _monU   = _usg.monitor || { used: 0, limit: 10  };
    const bars = [
      { l:'Audits',   v:_auditU.used, max:_auditU.limit, c:'#2563EB' },
      { l:'Monitors', v:_monU.used,   max:_monU.limit,   c:'#22c55e' },
    ];
    usageEl.innerHTML = bars.map(u => `
      <div class="fp-usage-bar-item">
        <div class="fp-usage-bar-row">
          <span class="fp-usage-bar-label">${u.l}</span>
          <span class="fp-usage-bar-val">${u.v}/${u.max}</span>
        </div>
        <div class="fp-usage-bar-track">
          <div class="fp-usage-bar-fill${u.v/u.max>0.8?' warn':''}" style="width:${(u.v/u.max*100).toFixed(1)}%;background:${u.v/u.max>0.8?'#ef4444':u.c}"></div>
        </div>
      </div>
    `).join('');
  }

  // User card
  const userEl = $('#sidebar-user');
  if (userEl) {
    const sitesCount = STATE.audits?.length || 6;
    const missionsActive = (STATE.missions||[]).filter(m=>m.status!=='done').length;
    const streak = STATE.streak || 0;
    userEl.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
        <div class="fp-user-avatar" style="width:46px;height:46px;font-size:18px;border-radius:12px;flex-shrink:0">${escHtml(me.firstName.charAt(0))}</div>
        <div style="flex:1;min-width:0">
          <div class="fp-user-name" style="font-size:14px;font-weight:700">${escHtml(me.firstName)} ${escHtml(me.lastName||'H.')}</div>
          <div style="font-size:10px;color:var(--fp-text-faint);margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(me.email||'')}</div>
          <div style="display:flex;align-items:center;gap:5px;margin-top:4px;flex-wrap:wrap">
            <span style="font-size:10px;padding:2px 8px;border-radius:100px;background:rgba(37,99,235,0.18);color:#4f8ef7;font-weight:700;letter-spacing:0.02em">Plan ${escHtml(me.plan)}</span>
            <span style="font-size:10px;color:var(--fp-text-faint)">${escHtml(me.role)}</span>
          </div>
        </div>
      </div>
      <div style="display:flex;gap:12px;padding-top:4px;border-top:1px solid rgba(255,255,255,0.05)">
        <span style="font-size:10px;color:var(--fp-text-faint);display:flex;align-items:center;gap:3px" title="${sitesCount} sites gérés">
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>
          ${sitesCount} sites
        </span>
        <span style="font-size:10px;color:var(--fp-text-faint);display:flex;align-items:center;gap:3px" title="${missionsActive} missions actives">
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
          ${missionsActive} missions
        </span>
        ${streak > 0 ? `<span style="font-size:10px;color:#f59e0b;display:flex;align-items:center;gap:3px;font-weight:600" title="${streak} jours de suite"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg>${streak}j</span>` : ''}
      </div>
    `;
  }

  // Topbar status
  const topDot = $('#topbar-status-dot');
  const topTxt = $('#topbar-status-text');
  const topStatus = $('#topbar-status');
  if (topDot) topDot.className = 'fp-status-dot' + (down > 0 ? ' down' : '');
  if (topTxt) topTxt.textContent = down > 0 ? `${down} DOWN` : 'Tous UP';
  if (topStatus) topStatus.className = 'fp-topbar-status' + (down > 0 ? ' down' : '');

  // Monitors badge in sidebar
  const monBadge = $('#monitors-badge');
  if (monBadge) { monBadge[down > 0 ? 'removeAttribute' : 'setAttribute']('hidden', ''); monBadge.textContent = down; }
}

