    const FEATURE_LABELS = { chat:'Chat IA', strategist:'IA Stratégiste', report_gen:'Génération rapports', mission_auto:'Missions auto', cro_analysis:'Analyses SEO', forecast:'Prévisions', market_intel:'Market Intel', audit_summary:'Audits IA' };
    const FEATURE_COLORS = ['#2563EB','#8b5cf6','#22c55e','#f59e0b','#06b6d4','#ef4444','#a855f7','#f97316'];
    const liveBreakdown = liveCredits?.byFeature ?? [];
    const totalBreakdownCredits = liveBreakdown.reduce((s,f)=>s+Number(f.credits),0) || 1;
    const usageBreakdown = liveBreakdown.length > 0
      ? liveBreakdown.map((f,i) => ({
          cat: FEATURE_LABELS[f.feature] || f.feature,
          credits: Number(f.credits),
          color: FEATURE_COLORS[i % FEATURE_COLORS.length],
          pct: Math.round(Number(f.credits)/totalBreakdownCredits*100),
          cost: Number(f.cost||0).toFixed(3),
        }))
      : [{ cat:'Aucune utilisation ce mois', credits:0, color:'#64748b', pct:100, cost:'0.000' }];

    const rawDaily = liveCredits?.dailyHistory ?? Array(30).fill(0);
    const dailyHistory = rawDaily.length === 30 ? rawDaily : Array(30).fill(0);
    const maxDaily = Math.max(...dailyHistory, 1);

    const alert90 = pct >= 90;
    const alert70 = pct >= 70 && pct < 90;
    const alertHtml = alert90
      ? `<div style="padding:12px 16px;background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.3);border-radius:var(--fp-radius-md);margin-bottom:16px;display:flex;align-items:center;gap:10px;flex-wrap:wrap"><span style="font-size:18px">🚨</span><div style="flex:1"><div style="font-size:13px;font-weight:700;color:#ef4444">90% de vos AI Credits utilisés</div><div style="font-size:11px;color:var(--fp-text-muted);margin-top:2px">Achetez un pack ou upgradez votre plan pour continuer à utiliser l\'IA sans interruption.</div></div><button class="fp-btn fp-btn-primary fp-btn-sm" onclick="navigateSub('plans')">Upgrader →</button></div>`
      : alert70
