function setupNewMissionPanel() {
  setTimeout(() => {
    $('#nm2-create')?.addEventListener('click', async () => {
      const title = $('#nm2-title')?.value.trim();
      if (!title) { showToast('warning','Entrez un titre'); return; }
      const m = { id:'ms'+Date.now(), title, category:$('#nm2-cat')?.value||'Audits', impact:$('#nm2-impact')?.value||'Élevé', status:'todo', date:$('#nm2-date')?.value||new Date().toISOString().slice(0,10) };
      STATE.missions.unshift(m);
      saveMissions();
      showToast('success','Mission créée !');
      closeFloatPanel();
      if (STATE.route === 'missions') render(); else navigate('missions');
      // Persistance backend (asynchrone, non bloquante)
      if (typeof window.FP_MISSIONS_API !== 'undefined') {
        const saved = await window.FP_MISSIONS_API.create(m);
        if (saved && saved.id && saved.id !== m.id) {
          const idx = STATE.missions.findIndex(x => x.id === m.id);
          if (idx >= 0) STATE.missions[idx].id = saved.id;
          saveMissions();
        }
      }
    });
  }, 50);
}

function renderExportPanel() {
  return `
    <div class="fp-form-group">
      <label class="fp-form-label">Type d\'export</label>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${[{v:'audits',l:'Audits SEO (CSV)'},{v:'monitors',l:'Monitors & uptime (CSV)'},{v:'missions',l:'Missions (CSV)'},{v:'all',l:'Export complet (ZIP)'}].map(o=>`
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:8px 12px;border:1px solid var(--fp-border);border-radius:8px;font-size:12px;color:var(--fp-text-soft)">
            <input type="radio" name="exp-type" value="${o.v}" style="accent-color:#2563EB" ${o.v==='audits'?'checked':''}/> ${o.l}
          </label>
        `).join('')}
      </div>
    </div>
    ${btn('Télécharger','fp-btn fp-btn-primary','download','id="exp-dl"')}
  `;
}
function setupExportPanel() {
  setTimeout(() => {
    $('#exp-dl')?.addEventListener('click', () => {
      const type = document.querySelector('input[name="exp-type"]:checked')?.value || 'audits';
      switch (type) {
        case 'audits':
          exportAuditsCsv(STATE.audits);
          break;
        case 'monitors': {
          const rows = (STATE.monitors || []).map(m =>
            `"${(m.name||'').replace(/"/g,'""')}","${(m.url||'').replace(/"/g,'""')}","${m.status||''}","${m.uptime||0}%","${m.latency||0}ms"`
          );
          exportCsv('Nom,URL,Statut,Uptime,Latence', rows, `monitors-flowpoint-${new Date().toISOString().slice(0,10)}.csv`);
          showToast('success', `CSV exporté — ${rows.length} monitor${rows.length>1?'s':''}`);
          break;
        }
        case 'missions': {
          const rows = (STATE.missions || []).map(m =>
            `"${(m.title||'').replace(/"/g,'""')}","${m.category||''}","${m.status||''}","${m.impact||''}","${m.date||''}"`
          );
          exportCsv('Titre,Catégorie,Statut,Impact,Échéance', rows, `missions-flowpoint-${new Date().toISOString().slice(0,10)}.csv`);
          showToast('success', `CSV exporté — ${rows.length} mission${rows.length>1?'s':''}`);
          break;
        }
        case 'all': {
          exportAuditsCsv(STATE.audits);
          setTimeout(() => {
            const rows = (STATE.missions || []).map(m =>
              `"${(m.title||'').replace(/"/g,'""')}","${m.category||''}","${m.status||''}"`
            );
            exportCsv('Titre,Catégorie,Statut', rows, `missions-flowpoint-${new Date().toISOString().slice(0,10)}.csv`);
          }, 400);
          break;
        }
      }
      closeFloatPanel();
    });
  }, 50);
}

