                <div style="font-size:10px;color:var(--fp-text-faint)">${r.size} · ${escHtml(r.date)}${r.brand ? ' · <span style="color:#8b5cf6">White-label</span>' : ''}${r.auto ? ' · <span style="color:#22c55e">Auto</span>' : ''}</div>
