// ── PSI helper functions for UI ───────────────────────────────────────────────

function fpMarkdown(text) {
  if (!text) return '';
  return text
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/`(.+?)`/g,'<code style="background:rgba(0,0,0,0.2);padding:2px 6px;border-radius:4px;font-family:\'JetBrains Mono\',monospace;font-size:0.9em">$1</code>')
    .replace(/^## (.+)$/gm,'<h3 style="font-size:16px;font-weight:700;margin:20px 0 8px;color:var(--fp-text)">$1</h3>')
    .replace(/^# (.+)$/gm,'<h2 style="font-size:18px;font-weight:800;margin:24px 0 10px;color:var(--fp-text)">$1</h2>')
    .replace(/^- (.+)$/gm,'<div style="display:flex;gap:8px;margin:4px 0;padding-left:4px"><span style="color:var(--fp-accent);flex-shrink:0">•</span><span>$1</span></div>')
    .replace(/^\d+\. (.+)$/gm,'<div style="display:flex;gap:8px;margin:6px 0"><span style="font-weight:700;color:var(--fp-accent);flex-shrink:0">›</span><span>$1</span></div>')
    .replace(/\n\n/g,'<br/><br/>')
    .replace(/\n/g,'<br/>');
}

async function fpAnalyzePSI() {
  const input = document.getElementById('fp-psi-url-input');
  const btn = document.getElementById('fp-psi-analyze-btn');
  const url = input && input.value.trim();
  if (!url) { showToast && showToast('error','Entrez une URL valide'); return; }

  if (btn) { btn.disabled = true; btn.textContent = 'Analyse en cours…'; }
  window._fpPsiAnalyzing = true;
  render();

  try {
    if (window.FP_PAGESPEED_API) {
      const result = await window.FP_PAGESPEED_API.analyze(url, { force: true });
      if (result) {
        showToast && showToast('success', 'Analyse terminée !');
      } else {
        showToast && showToast('error', 'Erreur lors de l\'analyse — URL accessible ?');
      }
    }
  } finally {
    window._fpPsiAnalyzing = false;
    if (btn) { btn.disabled = false; btn.textContent = 'Analyser'; }
    render();
  }
}

async function fpGetPSIAIReco() {
  const btn = document.getElementById('fp-psi-ai-btn');
  if (btn) btn.disabled = true;
  try {
    const psi = window.FP_DATA && window.FP_DATA.pagespeed;
    if (psi && window.FP_PAGESPEED_API) {
      await window.FP_PAGESPEED_API.getAIRecommendations(psi.url, psi.mobile, psi.desktop);
      showToast && showToast('success', 'Recommandations IA générées !');
    }
  } finally {
    if (btn) btn.disabled = false;
  }
}

// ── Wire analyze button after render (delegated — avoids function redeclaration hoisting conflict) ──
document.addEventListener('click', function(e) {
  if (e.target && e.target.closest && e.target.closest('#fp-psi-analyze-btn')) fpAnalyzePSI();
});
document.addEventListener('keydown', function(e) {
  if (e.target && e.target.id === 'fp-psi-url-input' && e.key === 'Enter') fpAnalyzePSI();
});

// ─────────────────────────────────────────────────────────────────────────────
// AI CHAT PANEL — Side assistant
// ─────────────────────────────────────────────────────────────────────────────

(function initAIChatPanel() {
  function openPanel() {
    const panel = document.getElementById('fp-ai-chat-panel');
    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (!panel || !overlay) return;
    panel.hidden = false;
    overlay.hidden = false;
    overlay.removeAttribute('aria-hidden');
    document.body.style.overflow = '';
    setTimeout(() => {
      const inp = document.getElementById('fp-ai-chat-input');
      if (inp) inp.focus();
    }, 300);
  }

  function closePanel() {
    const panel = document.getElementById('fp-ai-chat-panel');
    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (panel) panel.hidden = true;
    if (overlay) { overlay.hidden = true; overlay.setAttribute('aria-hidden','true'); }
  }

  function appendMessage(role, content, streaming) {
    const container = document.getElementById('fp-ai-chat-messages');
    if (!container) return null;
    // Hide welcome on first message
    const welcome = container.querySelector('.fp-ai-chat-welcome');
    if (welcome) welcome.style.display = 'none';

    const id = 'fp-ai-msg-' + Date.now();
    const initials = role === 'user' ? 'Vous' : 'IA';
    const div = document.createElement('div');
    div.className = `fp-ai-msg fp-ai-msg--${role}`;
    div.id = id;
    div.innerHTML = `
      <div class="fp-ai-msg-avatar">${role==='user'?'V':'🤖'}</div>
      <div class="fp-ai-msg-bubble">${streaming ? '<span class="fp-ai-cursor">▍</span>' : fpMarkdown(content)}</div>`;
    container.appendChild(div);
    container.scrollTop = container.scrollHeight;
    return id;
  }

  function updateMessage(id, content, done) {
    const el = document.getElementById(id);
    if (!el) return;
    const bubble = el.querySelector('.fp-ai-msg-bubble');
    if (bubble) bubble.innerHTML = done ? fpMarkdown(content) : fpMarkdown(content) + '<span class="fp-ai-cursor" style="animation:fpTyping 1s infinite">▍</span>';
    const container = document.getElementById('fp-ai-chat-messages');
    if (container) container.scrollTop = container.scrollHeight;
  }

  function setTyping(show) {
    const el = document.getElementById('fp-ai-chat-typing');
    if (el) el.hidden = !show;
  }

  function setSendEnabled(enabled) {
    const btn = document.getElementById('fp-ai-chat-send');
    if (btn) btn.disabled = !enabled;
  }

  function clearConversation() {
    const container = document.getElementById('fp-ai-chat-messages');
    if (!container) return;
    container.innerHTML = `<div class="fp-ai-chat-welcome">
      <div class="fp-ai-chat-welcome-icon">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/><circle cx="9" cy="14" r="1"/><circle cx="15" cy="14" r="1"/></svg>
      </div>
      <p><strong>Bonjour !</strong> Je suis votre assistant SEO Flowpoint.<br>Posez-moi des questions sur vos sites, performances, opportunités ou demandez-moi de générer un rapport.</p>
      <div class="fp-ai-chat-chips" id="fp-ai-chat-chips">
        <button class="fp-ai-quick-chip" data-msg="Quel est le score SEO moyen de mes sites ?">Score SEO moyen</button>
        <button class="fp-ai-quick-chip" data-msg="Quelles sont les 3 actions prioritaires à faire cette semaine ?">Actions prioritaires</button>
        <button class="fp-ai-quick-chip" data-msg="Analyse mes Core Web Vitals et donne-moi des recommandations.">Core Web Vitals</button>
        <button class="fp-ai-quick-chip" data-msg="Génère un résumé exécutif de la situation SEO.">Résumé exécutif</button>
      </div>
    </div>`;
    if (window.FP_AI_CHAT_API) window.FP_AI_CHAT_API.history = [];
    bindChips();
  }

  async function sendMessage(message) {
    if (!message || !message.trim()) return;
    const inp = document.getElementById('fp-ai-chat-input');
    if (inp) { inp.value = ''; inp.style.height = 'auto'; }
    setSendEnabled(false);

    appendMessage('user', message, false);
    setTyping(true);

    let msgId = null;
    let fullReply = '';

    try {
      if (window.FP_AI_CHAT_API) {
        await window.FP_AI_CHAT_API.sendMessage(message, {
          onDelta: function(delta, full) {
            setTyping(false);
            if (!msgId) {
              msgId = appendMessage('assistant', '', true);
            }
            fullReply = full;
            updateMessage(msgId, fullReply, false);
          },
          onDone: function(full) {
            setTyping(false);
            if (msgId) updateMessage(msgId, full, true);
            else appendMessage('assistant', full, false);
            setSendEnabled(true);
          },
        });
      } else {
        setTyping(false);
        appendMessage('assistant', 'Assistant IA non disponible.', false);
        setSendEnabled(true);
      }
    } catch(e) {
      setTyping(false);
      appendMessage('assistant', 'Erreur de connexion — réessayez.', false);
      setSendEnabled(true);
    }
  }

  function bindChips() {
    document.querySelectorAll('.fp-ai-quick-chip').forEach(chip => {
      if (chip._bound) return;
      chip._bound = true;
      chip.addEventListener('click', () => sendMessage(chip.dataset.msg));
    });
  }

  function bindPanel() {
    // Open panel — topbar AI button
    const topbarAI = document.getElementById('topbar-ai');
    if (topbarAI) topbarAI.addEventListener('click', openPanel);

    // Close
    const closeBtn = document.getElementById('fp-ai-chat-close');
    if (closeBtn) closeBtn.addEventListener('click', closePanel);

    const overlay = document.getElementById('fp-ai-chat-overlay');
    if (overlay) overlay.addEventListener('click', closePanel);

    // Fullscreen → navigate to AI page
    const fullBtn = document.getElementById('fp-ai-chat-fullpage');
    if (fullBtn) fullBtn.addEventListener('click', () => { closePanel(); if (typeof navigate === 'function') navigate('ai'); });

    // Clear
    const clearBtn = document.getElementById('fp-ai-chat-clear');
    if (clearBtn) clearBtn.addEventListener('click', clearConversation);

    // Input auto-resize + send enable
    const input = document.getElementById('fp-ai-chat-input');
    const sendBtn = document.getElementById('fp-ai-chat-send');

    if (input) {
      input.addEventListener('input', () => {
        input.style.height = 'auto';
        input.style.height = Math.min(input.scrollHeight, 120) + 'px';
        if (sendBtn) sendBtn.disabled = !input.value.trim();
      });
      input.addEventListener('keydown', e => {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          if (input.value.trim()) sendMessage(input.value.trim());
        }
      });
    }

    if (sendBtn) {
      sendBtn.addEventListener('click', () => {
        if (input && input.value.trim()) sendMessage(input.value.trim());
      });
    }

    // Chips
    bindChips();

    // Keyboard shortcut: Cmd/Ctrl+K or Cmd/Ctrl+I → toggle
    document.addEventListener('keydown', e => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'i') {
        e.preventDefault();
        const panel = document.getElementById('fp-ai-chat-panel');
        if (panel && panel.hidden) openPanel(); else closePanel();
      }
    });
  }

  // Initialize after DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindPanel);
  } else {
    bindPanel();
  }

  // Expose globally for context-aware calls from other pages
  window.fpOpenAIChat = openPanel;
  window.fpSendAIChat = sendMessage;
})();

// ═══════════════════════════════════════════════════════════════════════════════
// FP GITHUB API — client-side wrapper
// ═══════════════════════════════════════════════════════════════════════════════
window.FP_GITHUB_API = (() => {
  const base = (typeof window.FP_BASE_URL !== 'undefined' ? window.FP_BASE_URL : '') + '/api';

  async function _fetch(path, opts = {}) {
    const token = localStorage.getItem('fp_token') || (typeof window.FP_API_TOKEN !== 'undefined' ? window.FP_API_TOKEN : '');
    const res = await fetch(`${base}${path}`, {
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json', ...(opts.headers || {}) },
      ...opts,
    });
    if (!res.ok) { const e = await res.json().catch(() => ({})); throw new Error(e.error || `HTTP ${res.status}`); }
    return res.json();
  }

  return {
    getStatus: () => _fetch('/github/status'),
    getAuthUrl: () => _fetch('/github/auth'),
    getRepos: () => _fetch('/github/repos'),
    getCommits: (owner, repo, days = 30) => _fetch(`/github/commits/${owner}/${repo}?days=${days}`),
    getDeployments: (owner, repo) => _fetch(`/github/deployments/${owner}/${repo}`),
    analyzeRepo: (owner, repo) => _fetch(`/github/analysis/${owner}/${repo}`, { method: 'POST', body: '{}' }),
    getAnalysis: (owner, repo) => _fetch(`/github/analysis/${owner}/${repo}`),
    getIssues: (owner, repo) => _fetch(`/github/issues/${owner}/${repo}`),
    getHealth: (owner, repo) => _fetch(`/github/health/${owner}/${repo}`),
    getContributors: (owner, repo) => _fetch(`/github/contributors/${owner}/${repo}`),
    disconnect: () => _fetch('/github/disconnect', { method: 'POST', body: '{}' }),

    async connect() {
      try {
        const { url } = await _fetch('/github/auth');
        if (url) window.open(url, '_blank', 'width=600,height=700');
      } catch(e) { showToast('error', 'Connexion GitHub impossible : ' + e.message); }
    },
  };
})();

// ═══════════════════════════════════════════════════════════════════════════════
// FEATURE GATE HELPER
// ═══════════════════════════════════════════════════════════════════════════════
window.fpGate = function fpGate(feature, requiredPlan = 'pro') {
  const me = window.STATE?.me;
  const plan = (me?.plan || 'standard').toLowerCase();
  const order = { standard: 0, pro: 1, ultra: 2, agency: 2 };
  const userLevel = order[plan] ?? 0;
  const reqLevel = order[requiredPlan.toLowerCase()] ?? 1;
  return userLevel >= reqLevel;
};

window.fpGateBlock = function fpGateBlock(feature, requiredPlan = 'pro', title, desc) {
  if (window.fpGate(feature, requiredPlan)) return '';
  const planLabel = requiredPlan === 'ultra' ? 'Ultra' : 'Pro';
  return `<div style="padding:14px 16px;background:rgba(37,99,235,0.06);border:1px solid rgba(37,99,235,0.2);border-radius:var(--fp-radius-lg);margin-bottom:20px;display:flex;align-items:center;gap:12px">
    <div style="font-size:22px">🔒</div>
    <div style="flex:1">
      <div style="font-size:13px;font-weight:700;color:var(--fp-text);margin-bottom:2px">${title || feature} — ${planLabel} requis</div>
      <div style="font-size:12px;color:var(--fp-text-muted)">${desc || ''}</div>
    </div>
    <button class="fp-btn fp-btn-primary fp-btn-sm" style="flex-shrink:0" onclick="(typeof FP_BILLING_API!=='undefined'?FP_BILLING_API.checkout('${requiredPlan}'):navigate('billing'))">Passer ${planLabel}</button>
  </div>`;
};

