// DEPLOYMENTS PAGE
// ═══════════════════════════════════════════════════════════════════════════════
function renderDeployments() {
  const sub = STATE.subRoute;

  const _depTeam = STATE.team && STATE.team.length > 0 ? STATE.team : [];
  const _da = i => _depTeam.length > 0 ? (_depTeam[i % _depTeam.length].name || _depTeam[i % _depTeam.length].email || STATE.me?.name || '—') : (STATE.me?.name || '—');
  const DEPLOYS = [
    { repo:'flowpoint-app', env:'production', ref:'v2.8.1', status:'success', author:_da(0), duration:'3m 24s', time:new Date(Date.now()-1*86400000).toISOString(), commit:'feat: billing engine + GitHub OAuth' },
    { repo:'api-server',    env:'staging',    ref:'feat/billing-v2', status:'success', author:_da(1), duration:'2m 11s', time:new Date(Date.now()-2*86400000).toISOString(), commit:'chore: add v8 migrations + billing endpoints' },
    { repo:'marketing-site',env:'production', ref:'hotfix/meta-desc', status:'running', author:_da(2), duration:'—', time:new Date(Date.now()-3600000).toISOString(), commit:'fix: missing meta descriptions on 5 pages' },
    { repo:'api-server',    env:'production', ref:'v1.4.0', status:'failed', author:_da(0), duration:'1m 02s', time:new Date(Date.now()-2*86400000-3600000).toISOString(), commit:'fix: stripe webhook signature' },
    { repo:'flowpoint-app', env:'staging',    ref:'chore/deps', status:'success', author:_da(1), duration:'4m 38s', time:new Date(Date.now()-4*86400000).toISOString(), commit:'chore: update lodash, axios, moment' },
  ];

  return `
    <div class="fp-section-header">
      <div class="fp-section-title">Déploiements & CI/CD</div>
      <div class="fp-section-desc">Historique complet des déploiements, releases et workflows GitHub Actions.</div>
    </div>

    <div class="fp-stat-row fp-mb-20">
      ${statCard('Déploiements (30j)', displayStat(null, '8'), PREVIEW_MODE ? '7 succès · 1 échec' : 'Connectez GitHub', 'neutral')}
      ${statCard('Taux de succès', displayStat(null, '87.5%'), PREVIEW_MODE ? '+12% vs mois dernier' : 'Connectez GitHub', 'neutral')}
      ${statCard('Durée moyenne', displayStat(null, '2m 54s'), PREVIEW_MODE ? '-18s depuis l\'optimisation CI' : 'Connectez GitHub', 'neutral')}
      ${statCard('Dernier déploiement', displayStat(null, 'il y a 2h'), PREVIEW_MODE ? 'production · v2.8.1' : 'Connectez GitHub', 'neutral')}
    </div>

    <div class="fp-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <div class="fp-card-title" style="margin-bottom:0">🚀 Historique des déploiements</div>
        <div style="display:flex;gap:8px">
          <select style="background:var(--fp-surface-2);border:1px solid rgba(255,255,255,0.1);color:var(--fp-text);padding:5px 10px;border-radius:8px;font-size:11px">
            <option>Tous les dépôts</option>
            <option>flowpoint-app</option>
            <option>api-server</option>
            <option>marketing-site</option>
          </select>
          <select style="background:var(--fp-surface-2);border:1px solid rgba(255,255,255,0.1);color:var(--fp-text);padding:5px 10px;border-radius:8px;font-size:11px">
            <option>Tous les envs</option>
            <option>production</option>
            <option>staging</option>
          </select>
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${DEPLOYS.map(d => {
          const sc = d.status === 'success' ? '#22c55e' : d.status === 'running' ? '#3b82f6' : '#ef4444';
          const icon = d.status === 'success' ? '✓' : d.status === 'running' ? '↻' : '✕';
          const dt = new Date(d.time);
          const timeAgo = (() => { const diff = (Date.now() - dt.getTime()) / 1000; if (diff < 3600) return `il y a ${Math.floor(diff/60)}min`; if (diff < 86400) return `il y a ${Math.floor(diff/3600)}h`; return `il y a ${Math.floor(diff/86400)}j`; })();
          return `<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--fp-inner-card);border-radius:10px;border:1px solid rgba(255,255,255,0.04)">
            <div style="width:28px;height:28px;border-radius:50%;background:${sc}22;color:${sc};font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0">${icon}</div>
            <div style="flex:1;min-width:0">
              <div style="font-size:12px;font-weight:700;color:var(--fp-text)">${escHtml(d.repo)} → <span style="color:${sc}">${escHtml(d.env)}</span></div>
              <div style="font-size:11px;color:var(--fp-text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(d.commit)}</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-size:11px;font-weight:600;color:var(--fp-text-soft)">${escHtml(d.ref)}</div>
              <div style="font-size:10px;color:var(--fp-text-faint)">${escHtml(d.author)} · ${timeAgo}</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-size:11px;font-weight:600;color:var(--fp-text-muted)">${escHtml(d.duration)}</div>
              <span style="font-size:10px;color:${sc};background:${sc}18;padding:2px 8px;border-radius:20px">${escHtml(d.status)}</span>
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
}

