function renderRepositoryHealth() {
  const REPOS = [
    {
      name: 'flowpoint-app', lang: 'TypeScript', score: 92, label: 'Excellent',
      breakdown: { documentation: 35, activity: 25, deployment: 15, collaboration: 9, seo: 5, security: 3 },
      issues: [],
    },
    {
      name: 'api-server', lang: 'Node.js', score: 78, label: 'Bon',
      breakdown: { documentation: 25, activity: 22, deployment: 15, collaboration: 6, seo: 8, security: 2 },
      issues: ['Description manquante sur GitHub', 'Pas de topics configurés'],
    },
    {
      name: 'marketing-site', lang: 'Next.js', score: 61, label: 'À améliorer',
      breakdown: { documentation: 20, activity: 10, deployment: 15, collaboration: 4, seo: 10, security: 2 },
      issues: ['Inactif depuis 45 jours', '5 meta descriptions manquantes', 'Pas de sitemap.xml'],
    },
  ];

  return `
    <div class="fp-section-header">
      <div class="fp-section-title">Score de Santé des Dépôts</div>
      <div class="fp-section-desc">Évaluation complète de vos dépôts selon 6 dimensions : documentation, activité, déploiements, collaboration, SEO et sécurité.</div>
    </div>

    <div style="display:flex;flex-direction:column;gap:16px">
      ${REPOS.map(r => {
        const hColor = r.score >= 80 ? '#22c55e' : r.score >= 60 ? '#f59e0b' : '#ef4444';
        const totalBreakdown = Object.values(r.breakdown).reduce((a, b) => a + b, 0);
        return `<div class="fp-card">
          <div style="display:flex;align-items:flex-start;gap:16px">
            <div style="position:relative;width:80px;height:80px;flex-shrink:0">
              <svg viewBox="0 0 36 36" style="width:80px;height:80px;transform:rotate(-90deg)">
                <circle cx="18" cy="18" r="15.9" fill="none" stroke="rgba(255,255,255,0.08)" stroke-width="3"/>
                <circle cx="18" cy="18" r="15.9" fill="none" stroke="${hColor}" stroke-width="3"
                  stroke-dasharray="${r.score} ${100 - r.score}" stroke-linecap="round"/>
              </svg>
              <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center">
                <div style="font-size:18px;font-weight:900;color:${hColor};line-height:1">${r.score}</div>
                <div style="font-size:8px;color:var(--fp-text-faint)">/100</div>
              </div>
            </div>
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
                <div style="font-size:15px;font-weight:800;color:var(--fp-text)">${escHtml(r.name)}</div>
                <span style="font-size:10px;background:rgba(37,99,235,0.12);color:#93c5fd;padding:2px 8px;border-radius:20px">${escHtml(r.lang)}</span>
                <span style="font-size:10px;font-weight:700;color:${hColor};background:${hColor}18;padding:2px 8px;border-radius:20px">${escHtml(r.label)}</span>
              </div>
              <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin-bottom:10px">
                ${Object.entries(r.breakdown).map(([key, val]) => {
                  const maxVal = { documentation:35,activity:25,deployment:15,collaboration:10,seo:10,security:5 }[key] || 10;
                  const pct = Math.round((val / maxVal) * 100);
                  const c = pct >= 80 ? '#22c55e' : pct >= 50 ? '#f59e0b' : '#ef4444';
                  return `<div style="text-align:center">
                    <div style="font-size:12px;font-weight:700;color:${c}">${val}</div>
                    <div style="font-size:9px;color:var(--fp-text-faint);text-transform:capitalize">${key}</div>
                    <div style="height:3px;background:var(--fp-track);border-radius:2px;margin-top:3px">
                      <div style="height:100%;width:${pct}%;background:${c};border-radius:2px"></div>
                    </div>
                  </div>`;
                }).join('')}
              </div>
              ${r.issues.length ? `<div style="display:flex;flex-direction:column;gap:4px">
                ${r.issues.map(i => `<div style="font-size:11px;color:var(--fp-text-muted);display:flex;align-items:center;gap:6px">
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                  ${escHtml(i)}
                </div>`).join('')}
              </div>` : `<div style="font-size:11px;color:#22c55e;display:flex;align-items:center;gap:6px">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#22c55e" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                Excellent état — aucun problème critique détecté
              </div>`}
            </div>
            <button class="fp-btn fp-btn-ghost fp-btn-sm" style="flex-shrink:0" onclick="navigate('code-analysis')">Analyser</button>
          </div>
        </div>`;
      }).join('')}
    </div>

    <div class="fp-card" style="margin-top:16px">
      <div class="fp-card-title">📋 Recommandations prioritaires</div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${[
          { priority:'P0', title:'Mettre à jour lodash dans mobile-client', repo:'mobile-client', impact:'Sécurité critique', effort:'5 min', cmd:'npm install lodash@4.17.21' },
          { priority:'P1', title:'Ajouter description à api-server', repo:'api-server', impact:'SEO + Discoverabilité', effort:'2 min', cmd:'GitHub > Settings > Edit description' },
          { priority:'P1', title:'Relancer marketing-site (inactif 45j)', repo:'marketing-site', impact:'Fraîcheur du contenu', effort:'30 min', cmd:'Pousser les meta descriptions manquantes' },
          { priority:'P2', title:'Nettoyer les 28 branches de flowpoint-app', repo:'flowpoint-app', impact:'Collaboration', effort:'15 min', cmd:'git branch --merged | xargs git branch -d' },
        ].map(r => {
          const pc = r.priority === 'P0' ? '#ef4444' : r.priority === 'P1' ? '#f59e0b' : '#3b82f6';
          return `<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--fp-inner-card);border-radius:8px">
            <span style="font-size:10px;font-weight:800;color:${pc};background:${pc}18;padding:2px 8px;border-radius:20px;flex-shrink:0">${r.priority}</span>
            <div style="flex:1;min-width:0">
              <div style="font-size:12px;font-weight:600;color:var(--fp-text)">${escHtml(r.title)}</div>
              <div style="font-size:10px;color:var(--fp-text-faint);font-family:monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(r.cmd)}</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-size:10px;color:var(--fp-text-muted)">${escHtml(r.impact)}</div>
              <div style="font-size:10px;color:var(--fp-text-faint)">${escHtml(r.effort)}</div>
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
}

// ── FP BILLING API extensions ──────────────────────────────────────────────────
if (typeof window.FP_BILLING_API !== 'undefined' && window.FP_BILLING_API) {
  const _existingCheckout = window.FP_BILLING_API.checkout?.bind(window.FP_BILLING_API);
  window.FP_BILLING_API.getPlans     = () => apiFetch('/api/billing/plans').catch(() => null);
  window.FP_BILLING_API.getUsage     = () => apiFetch('/api/billing/usage').catch(() => null);
  window.FP_BILLING_API.getAnalytics = () => apiFetch('/api/billing/analytics').catch(() => null);
  window.FP_BILLING_API.getInvoices  = () => apiFetch('/api/billing/invoices').catch(() => null);
  window.FP_BILLING_API.getMRR       = () => apiFetch('/api/billing/mrr').catch(() => null);
  window.FP_BILLING_API.startTrial   = (plan='pro',days=14) => apiFetch('/api/billing/trial',{method:'POST',body:JSON.stringify({plan,days})}).catch(()=>null);
  window.FP_BILLING_API.validateCoupon = (code) => apiFetch('/api/billing/coupon/validate',{method:'POST',body:JSON.stringify({code})}).catch(()=>null);
  window.FP_BILLING_API.getSubscription = () => apiFetch('/api/billing/subscription').catch(()=>null);
}

// ── Auth providers ─────────────────────────────────────────────────────────────
window.FP_AUTH = {
  async loginWithGoogle() {
    try {
      const d = await apiFetch('/api/auth/google/login');
      if (d?.url) window.location.href = d.url;
    } catch(e) { showToast('error','Google OAuth non configuré'); }
  },
  async loginWithGitHub() {
    try {
      const d = await apiFetch('/api/auth/github/login');
      if (d?.url) window.location.href = d.url;
    } catch(e) { showToast('error','GitHub OAuth non configuré'); }
  },
  getProviders: () => apiFetch('/api/auth/providers').catch(() => ({ providers: [] })),
  getSession:   () => apiFetch('/api/auth/session').catch(() => null),
  logout:       () => apiFetch('/api/auth/logout', { method: 'POST' }).catch(() => null),
};


// ═══════════════════════════════════════════════════════════════════════════════
// SEARCH CONSOLE PAGE
// ═══════════════════════════════════════════════════════════════════════════════

function _gscConnected() { return !!(STATE.gsc?.connected); }
function _gscSite()      { return STATE.gsc?.siteUrl || ''; }

function renderSearchConsole() {
  const sub = STATE.subRoute;
  const gsc = STATE.gsc || {};
  const connected = _gscConnected();

  if (!connected && !STATE._gscLoading && !STATE._gscLoaded) {
    STATE._gscLoading = true;
    window.FP_GSC_API && window.FP_GSC_API.load().finally(() => {
      STATE._gscLoading = false;
      STATE._gscLoaded = true;
      render();
    });
  }

  if (!connected) {
    return `
      <div class="fp-section-header">
        <div class="fp-section-title">Google Search Console</div>
        <div class="fp-section-sub">Connectez GSC pour suivre vos mots-clés, impressions, CTR et position moyenne en temps réel.</div>
      </div>
      <div class="fp-gsc-connect-card">
        <div class="fp-gsc-connect-icon">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#4285F4" stroke-width="1.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        </div>
        <div class="fp-gsc-connect-title">Connectez Google Search Console</div>
        <div class="fp-gsc-connect-desc">Visualisez vos performances organiques — impressions, clics, CTR, position — directement dans FlowPoint.</div>
        <div class="fp-gsc-connect-features">
          ${['📊 Top mots-clés par impressions & CTR', '📄 Pages les plus performantes', '🔍 Évolution des positions sur 90 jours', '🗺️ Couverture géographique & devices', '⚡ Statut d\'indexation des URLs'].map(f => `
            <div class="fp-gsc-connect-feature"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#22c55e" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> ${f}</div>
          `).join('')}
        </div>
        <button class="fp-btn fp-btn-primary" style="margin-top:24px;padding:10px 28px;font-size:14px" onclick="window.FP_GSC_API&&window.FP_GSC_API.openConnect()">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right:8px;vertical-align:middle"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
          Connecter Search Console
        </button>
      </div>`;
  }

  const status = gsc;
  const keywords = gsc.keywords || [];
  const pages = gsc.pages || [];
  const timeSeries = gsc.timeSeries || [];

  const statsRow = `
    <div class="fp-stat-row fp-mb-20">
      ${statCard('Clics (30j)', (status.clicksTotal||0).toLocaleString('fr-FR'), 'Depuis GSC', 'up')}
      ${statCard('Impressions (30j)', (status.impressionsTotal||0).toLocaleString('fr-FR'), 'Depuis GSC', 'up')}
      ${statCard('CTR moyen', (status.avgCTR||0).toFixed(2)+'%', 'Taux de clic', status.avgCTR > 3 ? 'up' : 'down')}
      ${statCard('Position moy.', (status.avgPosition||0).toFixed(1), 'Rang SERP', status.avgPosition < 10 ? 'up' : 'down')}
    </div>`;

  const siteHeader = `
    <div class="fp-gsc-site-header">
      <div>
        <div class="fp-section-title">Search Console</div>
        <div class="fp-section-sub">Site : <strong>${escHtml(status.siteDisplayName||_gscSite())}</strong> · Dernière sync : ${status.lastSync ? new Date(status.lastSync).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}) : 'jamais'}</div>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window.FP_GSC_API&&window.FP_GSC_API.sync().then(()=>showToast('success','Sync GSC lancée'))">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg> Synchroniser
        </button>
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="navigateSub('connect')">Sites ▾</button>
        <button class="fp-btn fp-btn-ghost fp-btn-sm fp-btn-danger" onclick="if(confirm('Déconnecter GSC ?'))window.FP_GSC_API&&window.FP_GSC_API.disconnect().then(()=>render())">Déconnecter</button>
      </div>
    </div>`;

  if (sub === 'connect') {
    return `${siteHeader}${renderGSCConnect(gsc)}`;
  }

  if (sub === 'keywords') {
    return `${siteHeader}${statsRow}${renderGSCKeywords(keywords, gsc)}`;
  }

  if (sub === 'pages') {
    return `${siteHeader}${statsRow}${renderGSCPages(pages, gsc)}`;
  }

  if (sub === 'impressions') {
    return `${siteHeader}${statsRow}${renderGSCImpressions(timeSeries, gsc)}`;
  }

  if (sub === 'indexing') {
    return `${siteHeader}${renderGSCIndexing(gsc)}`;
  }

  const _gscAiBlock = aiBlock(
    `${(gsc.clicksTotal||0).toLocaleString('fr-FR')} clics · ${(gsc.impressionsTotal||0).toLocaleString('fr-FR')} impressions · CTR <strong>${(gsc.avgCTR||0).toFixed(2)}%</strong> · Position moyenne <strong>${(gsc.avgPosition||0).toFixed(1)}</strong>. ${(gsc.avgCTR||0) < 3 ? 'CTR faible — optimisez vos balises title et meta description.' : (gsc.avgPosition||0) > 20 ? 'Position éloignée du top 10 — ciblez vos mots-clés à fort potentiel.' : 'Bonne visibilité organique. Analysez vos top mots-clés pour de nouvelles opportunités.'}`,
    ['Optimiser le CTR', 'Top mots-clés', 'Opportunités manquées']
  );
  return `${siteHeader}${statsRow}${_gscAiBlock}${renderGSCOverview(keywords, pages, timeSeries, gsc)}`;
}

function renderGSCOverview(keywords, pages, timeSeries, gsc) {
  const topKw = keywords.slice(0, 5);
  const topPg = pages.slice(0, 5);
  const tsSample = timeSeries.slice(-30);

  return `
    ${timeSeries.length ? `
    <div class="fp-card fp-mb-20">
      <div class="fp-card-title">📈 Évolution clics & impressions (30 derniers jours)</div>
      <div style="display:flex;gap:16px;margin-bottom:12px;flex-wrap:wrap">
        <div style="display:flex;align-items:center;gap:6px"><div style="width:12px;height:3px;background:#2563EB;border-radius:2px"></div><span style="font-size:11px;color:var(--fp-text-muted)">Clics</span></div>
        <div style="display:flex;align-items:center;gap:6px"><div style="width:12px;height:3px;background:#f59e0b;border-radius:2px"></div><span style="font-size:11px;color:var(--fp-text-muted)">Impressions</span></div>
      </div>
      <div class="fp-gsc-chart" id="gsc-overview-chart">
        ${(() => {
          if (!tsSample.length) return '<div style="padding:32px;text-align:center;color:var(--fp-text-faint);font-size:12px">Chargement du graphique…</div>';
          const maxImp = Math.max(...tsSample.map(r => parseInt(r.impressions||0)), 1);
          const maxClk = Math.max(...tsSample.map(r => parseInt(r.clicks||0)), 1);
          const w = 800, h = 160;
          const pts1 = tsSample.map((r, i) => { const x = (i/(tsSample.length-1))*w; const y = h - (parseInt(r.clicks||0)/maxClk)*h*0.85 - 8; return `${x.toFixed(1)},${y.toFixed(1)}`; });
          const pts2 = tsSample.map((r, i) => { const x = (i/(tsSample.length-1))*w; const y = h - (parseInt(r.impressions||0)/maxImp)*h*0.85 - 8; return `${x.toFixed(1)},${y.toFixed(1)}`; });
          return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:160px;overflow:visible">
            <defs><linearGradient id="gscG1" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2563EB" stop-opacity="0.15"/><stop offset="100%" stop-color="#2563EB" stop-opacity="0"/></linearGradient></defs>
            <polyline points="${pts1.join(' ')}" fill="none" stroke="#2563EB" stroke-width="2" stroke-linejoin="round"/>
            <polyline points="${pts2.join(' ')}" fill="none" stroke="#f59e0b" stroke-width="1.5" stroke-linejoin="round" stroke-dasharray="4,2"/>
          </svg>`;
        })()}
      </div>
    </div>` : ''}

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px">
      <div class="fp-card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
          <div class="fp-card-title" style="margin-bottom:0">🔑 Top Mots-clés</div>
          <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="navigateSub('keywords')">Voir tout →</button>
        </div>
        ${topKw.length ? `
        <div class="fp-gsc-kw-table">
          <div class="fp-gsc-table-header"><span>Requête</span><span>Clics</span><span>Impr.</span><span>CTR</span><span>Pos.</span></div>
          ${topKw.map(kw => `
            <div class="fp-gsc-table-row">
              <span style="font-size:11px;color:var(--fp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(String(kw.keyword||''))}">${escHtml(String(kw.keyword||''))}</span>
              <span style="color:#2563EB;font-weight:700">${parseInt(String(kw.clicks||0)).toLocaleString('fr-FR')}</span>
              <span style="color:var(--fp-text-muted)">${parseInt(String(kw.impressions||0)).toLocaleString('fr-FR')}</span>
              <span style="color:${parseFloat(String(kw.ctr||0))>3?'#22c55e':'#f59e0b'}">${parseFloat(String(kw.ctr||0)).toFixed(1)}%</span>
              <span style="color:${parseFloat(String(kw.position||99))<10?'#22c55e':parseFloat(String(kw.position||99))<20?'#f59e0b':'#ef4444'}">${parseFloat(String(kw.position||0)).toFixed(1)}</span>
            </div>
          `).join('')}
        </div>` : '<div style="padding:24px;text-align:center;color:var(--fp-text-faint);font-size:12px">Aucune donnée — synchronisez GSC</div>'}
      </div>

      <div class="fp-card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
          <div class="fp-card-title" style="margin-bottom:0">📄 Top Pages</div>
          <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="navigateSub('pages')">Voir tout →</button>
        </div>
        ${topPg.length ? `
        <div class="fp-gsc-kw-table">
          <div class="fp-gsc-table-header"><span>Page</span><span>Clics</span><span>Impr.</span><span>CTR</span><span>Pos.</span></div>
          ${topPg.map(pg => {
            const url = String(pg.page||'');
            const path = url.replace(/^https?:\/\/[^/]+/, '') || url;
            return `<div class="fp-gsc-table-row">
              <span style="font-size:11px;color:var(--fp-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(url)}">${escHtml(path)}</span>
              <span style="color:#2563EB;font-weight:700">${parseInt(String(pg.clicks||0)).toLocaleString('fr-FR')}</span>
              <span style="color:var(--fp-text-muted)">${parseInt(String(pg.impressions||0)).toLocaleString('fr-FR')}</span>
              <span style="color:${parseFloat(String(pg.ctr||0))>3?'#22c55e':'#f59e0b'}">${parseFloat(String(pg.ctr||0)).toFixed(1)}%</span>
              <span style="color:${parseFloat(String(pg.position||99))<10?'#22c55e':parseFloat(String(pg.position||99))<20?'#f59e0b':'#ef4444'}">${parseFloat(String(pg.position||0)).toFixed(1)}</span>
            </div>`;
          }).join('')}
        </div>` : '<div style="padding:24px;text-align:center;color:var(--fp-text-faint);font-size:12px">Aucune donnée — synchronisez GSC</div>'}
      </div>
    </div>`;
}

function renderGSCKeywords(keywords, gsc) {
  const sorted = [...keywords].sort((a,b) => parseInt(String(b.impressions||0)) - parseInt(String(a.impressions||0)));
  return `
    <div class="fp-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <div class="fp-card-title" style="margin-bottom:0">🔑 Tous les mots-clés — ${sorted.length} requêtes</div>
        <div style="font-size:11px;color:var(--fp-text-faint)">30 derniers jours · Triés par impressions</div>
      </div>
      ${sorted.length ? `
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="border-bottom:1px solid rgba(255,255,255,0.07)">
              <th style="text-align:left;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">#</th>
              <th style="text-align:left;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Requête</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Clics</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Impressions</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">CTR</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Position</th>
            </tr>
          </thead>
          <tbody>
            ${sorted.map((kw, i) => {
              const pos = parseFloat(String(kw.position||99));
              const ctr = parseFloat(String(kw.ctr||0));
              const posColor = pos < 3 ? '#22c55e' : pos < 10 ? '#4ade80' : pos < 20 ? '#f59e0b' : '#ef4444';
              return `<tr style="border-top:1px solid rgba(255,255,255,0.04);${i%2===0?'':'background:rgba(255,255,255,0.01)'}">
                <td style="padding:8px 10px;font-size:11px;color:var(--fp-text-faint)">${i+1}</td>
                <td style="padding:8px 10px;font-size:12px;color:var(--fp-text);max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(String(kw.keyword||''))}</td>
                <td style="padding:8px 10px;font-size:12px;font-weight:700;color:#2563EB;text-align:right">${parseInt(String(kw.clicks||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:8px 10px;font-size:12px;color:var(--fp-text-muted);text-align:right">${parseInt(String(kw.impressions||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:8px 10px;font-size:12px;font-weight:600;color:${ctr>3?'#22c55e':'#f59e0b'};text-align:right">${ctr.toFixed(2)}%</td>
                <td style="padding:8px 10px;text-align:right"><span style="font-size:11px;font-weight:700;color:${posColor};background:${posColor}15;padding:2px 8px;border-radius:20px">${pos.toFixed(1)}</span></td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>` : '<div style="padding:32px;text-align:center;color:var(--fp-text-faint);font-size:13px">Aucun mot-clé — lancez une synchronisation pour charger les données.</div>'}
    </div>`;
}

function renderGSCPages(pages, gsc) {
  const sorted = [...pages].sort((a,b) => parseInt(String(b.clicks||0)) - parseInt(String(a.clicks||0)));
  return `
    <div class="fp-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <div class="fp-card-title" style="margin-bottom:0">📄 Top Pages — ${sorted.length} URLs</div>
        <div style="font-size:11px;color:var(--fp-text-faint)">30 derniers jours · Triées par clics</div>
      </div>
      ${sorted.length ? `
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="border-bottom:1px solid rgba(255,255,255,0.07)">
              <th style="text-align:left;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">#</th>
              <th style="text-align:left;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">URL</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Clics</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Impressions</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">CTR</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--fp-text-faint)">Position</th>
            </tr>
          </thead>
          <tbody>
            ${sorted.map((pg, i) => {
              const url = String(pg.page||'');
              const path = url.replace(/^https?:\/\/[^/]+/, '') || url;
              const pos = parseFloat(String(pg.position||99));
              const ctr = parseFloat(String(pg.ctr||0));
              const posColor = pos < 3 ? '#22c55e' : pos < 10 ? '#4ade80' : pos < 20 ? '#f59e0b' : '#ef4444';
              return `<tr style="border-top:1px solid rgba(255,255,255,0.04);${i%2===0?'':'background:rgba(255,255,255,0.01)'}">
                <td style="padding:8px 10px;font-size:11px;color:var(--fp-text-faint)">${i+1}</td>
                <td style="padding:8px 10px;font-size:12px;color:var(--fp-text);max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(url)}">${escHtml(path)}</td>
                <td style="padding:8px 10px;font-size:12px;font-weight:700;color:#2563EB;text-align:right">${parseInt(String(pg.clicks||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:8px 10px;font-size:12px;color:var(--fp-text-muted);text-align:right">${parseInt(String(pg.impressions||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:8px 10px;font-size:12px;font-weight:600;color:${ctr>3?'#22c55e':'#f59e0b'};text-align:right">${ctr.toFixed(2)}%</td>
                <td style="padding:8px 10px;text-align:right"><span style="font-size:11px;font-weight:700;color:${posColor};background:${posColor}15;padding:2px 8px;border-radius:20px">${pos.toFixed(1)}</span></td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>` : '<div style="padding:32px;text-align:center;color:var(--fp-text-faint);font-size:13px">Aucune page — synchronisez GSC.</div>'}
    </div>`;
}

function renderGSCImpressions(timeSeries, gsc) {
  const sorted = [...timeSeries].sort((a,b) => String(a.date||'').localeCompare(String(b.date||'')));
  const last30 = sorted.slice(-30);
  const last7  = sorted.slice(-7);

  const sum7 = last7.reduce((s,r) => ({
    clicks: (s.clicks||0) + parseInt(String(r.clicks||0)),
    impressions: (s.impressions||0) + parseInt(String(r.impressions||0)),
  }), { clicks: 0, impressions: 0 });

  const sum30 = last30.reduce((s,r) => ({
    clicks: (s.clicks||0) + parseInt(String(r.clicks||0)),
    impressions: (s.impressions||0) + parseInt(String(r.impressions||0)),
  }), { clicks: 0, impressions: 0 });

  return `
    <div class="fp-stat-row fp-mb-20" style="grid-template-columns:repeat(4,1fr)">
      ${statCard('Clics 7j', sum7.clicks.toLocaleString('fr-FR'), '', 'up')}
      ${statCard('Impressions 7j', sum7.impressions.toLocaleString('fr-FR'), '', 'up')}
      ${statCard('Clics 30j', sum30.clicks.toLocaleString('fr-FR'), '', 'up')}
      ${statCard('Impressions 30j', sum30.impressions.toLocaleString('fr-FR'), '', 'up')}
    </div>

    <div class="fp-card">
      <div class="fp-card-title">📈 Clics & Impressions — évolution quotidienne</div>
      ${sorted.length ? `
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;min-width:500px">
          <thead>
            <tr style="border-bottom:1px solid rgba(255,255,255,0.07)">
              <th style="text-align:left;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--fp-text-faint)">Date</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--fp-text-faint)">Clics</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--fp-text-faint)">Impressions</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--fp-text-faint)">CTR</th>
              <th style="text-align:right;padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;color:var(--fp-text-faint)">Position</th>
            </tr>
          </thead>
          <tbody>
            ${sorted.slice().reverse().slice(0,90).map((r,i) => {
              const ctr = parseFloat(String(r.ctr||0));
              const pos = parseFloat(String(r.avg_position||0));
              return `<tr style="border-top:1px solid rgba(255,255,255,0.04);${i%2===0?'':'background:rgba(255,255,255,0.01)'}">
                <td style="padding:7px 10px;font-size:12px;color:var(--fp-text)">${String(r.date||'')}</td>
                <td style="padding:7px 10px;font-size:12px;font-weight:700;color:#2563EB;text-align:right">${parseInt(String(r.clicks||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:7px 10px;font-size:12px;color:var(--fp-text-muted);text-align:right">${parseInt(String(r.impressions||0)).toLocaleString('fr-FR')}</td>
                <td style="padding:7px 10px;font-size:12px;color:${ctr>3?'#22c55e':'#f59e0b'};text-align:right">${ctr.toFixed(2)}%</td>
                <td style="padding:7px 10px;font-size:12px;color:${pos<10?'#22c55e':'#f59e0b'};text-align:right">${pos.toFixed(1)}</td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
      </div>` : '<div style="padding:32px;text-align:center;color:var(--fp-text-faint)">Aucune donnée temporelle disponible.</div>'}
    </div>`;
}

function renderGSCIndexing(gsc) {
  return `
    <div class="fp-card">
      <div class="fp-card-title">🔍 Inspection & Indexation d\'URLs</div>
      <div style="font-size:12px;color:var(--fp-text-muted);margin-bottom:16px">Vérifiez si une URL est indexée par Google et obtenir des détails d\'inspection.</div>
      <div style="display:flex;gap:10px;margin-bottom:20px">
        <input id="gsc-url-inspect" type="url" placeholder="https://votre-site.com/page" style="flex:1;background:var(--fp-track);border:1px solid rgba(255,255,255,0.12);border-radius:10px;padding:10px 14px;color:var(--fp-text);font-size:13px;outline:none" />
        <button class="fp-btn fp-btn-primary" onclick="(async()=>{
          const url = document.getElementById('gsc-url-inspect')?.value?.trim();
          if (!url) return showToast('error','Entrez une URL valide');
          showToast('info','Inspection en cours…');
          try {
            const r = await apiFetch('/api/gsc/indexing', {method:'POST', body: JSON.stringify({inspectionUrl:url})});
            showToast(r.ok?'success':'error', r.ok ? 'URL inspectée — voir console' : String(r.error));
            console.log('[GSC Indexing]', r);
          } catch(e) { showToast('error', String(e)); }
        })()">Inspecter</button>
      </div>
      <div style="padding:24px;background:var(--fp-inner-card);border-radius:12px;border:1px dashed rgba(255,255,255,0.1);text-align:center">
        <div style="font-size:32px;margin-bottom:12px">🔍</div>
        <div style="font-size:13px;font-weight:600;color:var(--fp-text);margin-bottom:6px">Statut d\'indexation</div>
        <div style="font-size:12px;color:var(--fp-text-muted)">Entrez une URL ci-dessus pour obtenir son statut d\'indexation Google, les données de crawl, et les problèmes potentiels.</div>
      </div>
    </div>`;
}

function renderGSCConnect(gsc) {
  return `
    <div class="fp-card">
      <div class="fp-card-title">⚙ Sélectionner un site Search Console</div>
      <div style="font-size:12px;color:var(--fp-text-muted);margin-bottom:20px">Choisissez la propriété GSC à analyser. Seules les propriétés auxquelles vous avez accès sont listées.</div>
      <div id="gsc-sites-list">
        <div style="padding:16px;text-align:center;color:var(--fp-text-faint)">
          <button class="fp-btn fp-btn-primary" onclick="(async()=>{
            this.disabled=true;this.textContent='Chargement…';
            try {
              const r = await apiFetch('/api/gsc/sites');
              const sites = r.sites||[];
              const active = r.activeSite;
              if (!sites.length) { showToast('info','Aucun site GSC trouvé. Vérifiez vos accès.'); this.disabled=false;this.textContent='Charger les sites';return; }
              const container = this.closest('#gsc-sites-list')||this.parentElement;
              container.innerHTML = sites.map(s => \`<div style='display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:10px;border:1px solid \${s.siteUrl===active?'rgba(37,99,235,0.4)':'rgba(255,255,255,0.08)'};background:\${s.siteUrl===active?'rgba(37,99,235,0.08)':'var(--fp-inner-card)'};margin-bottom:8px'>
                <svg width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2'><circle cx='12' cy='12' r='10'/><line x1='2' y1='12' x2='22' y2='12'/><path d='M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z'/></svg>
                <div style='flex:1;min-width:0'>
                  <div style='font-size:12px;font-weight:600;color:var(--fp-text)'>\${escHtml(s.siteUrl)}</div>
                  <div style='font-size:10px;color:var(--fp-text-faint)'>\${escHtml(s.permissionLevel||'')}</div>
                </div>
                \${s.siteUrl===active?'<span style="font-size:10px;color:#22c55e;font-weight:700">● Actif</span>':'<button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window.FP_GSC_API&&window.FP_GSC_API.selectSite(\''+escHtml(s.siteUrl)+'\').then(()=>render())">Sélectionner</button>'}
              </div>\`).join('');
            } catch(e) { showToast('error',String(e));this.disabled=false;this.textContent='Réessayer'; }
          })()">Charger les sites disponibles</button>
        </div>
      </div>
    </div>`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// FP GBP API — Real Google Business Profile data client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_GBP_API = {
  async load() {
    try {
      const status = await apiFetch('/api/google/status').catch(() => null);
      if (!status?.connected) {
        STATE.gbp = { connected: false };
        return;
      }
      const [locsData, reviewsData] = await Promise.all([
        apiFetch('/api/google/locations').catch(() => ({ locations: [] })),
        apiFetch('/api/google/reviews?limit=20').catch(() => ({ reviews: [] })),
      ]);
      STATE.gbp = {
        connected: true,
        email: status.email || '',
        lastSync: status.lastSync,
        locationsCount: status.locationsCount || 0,
        reviewsCount: status.reviewsCount || 0,
        avgRating: status.avgRating || null,
        locations: locsData?.locations || [],
        reviews: reviewsData?.reviews || [],
        performance: null,
      };
      if (STATUS?.gbp?.locations?.length && !STATE.gbp.performance) {
        const perfData = await apiFetch('/api/google/performance').catch(() => null);
        if (perfData?.ok) STATE.gbp.performance = perfData.data || null;
      }
    } catch(e) {
      console.warn('[FP_GBP_API] load error:', e);
      STATE.gbp = { connected: false };
    }
  },

  async sync() {
    showToast('info', 'Synchronisation GBP lancée…');
    try {
      const r = await apiFetch('/api/google/sync', { method: 'POST' });
      if (r?.ok) {
        showToast('success', `GBP synchronisé — ${r.locationsCount||0} établissements, ${r.reviewsCount||0} avis`);
        await this.load();
        render();
      } else {
        showToast('error', r?.error || 'Sync GBP échouée');
      }
    } catch(e) { showToast('error', String(e)); }
  },

  async openConnect() {
    try {
      const d = await apiFetch('/api/auth/google/login');
      if (d?.url) window.location.href = d.url;
      else showToast('error', 'Google OAuth non configuré');
    } catch(e) { showToast('error', 'Impossible de démarrer Google OAuth'); }
  },

  async disconnect() {
    showToast('info', 'Déconnexion Google…');
    try {
      await apiFetch('/api/google/disconnect', { method: 'POST' });
      STATE.gbp = { connected: false };
      showToast('success', 'Google déconnecté');
    } catch(e) { showToast('error', String(e)); }
  },

  async replyToReview(reviewId, reply) {
    const r = await apiFetch('/api/google/reviews/' + encodeURIComponent(reviewId) + '/reply', {
      method: 'POST', body: JSON.stringify({ reply })
    });
    if (r?.ok) { showToast('success', 'Réponse publiée'); await this.load(); render(); }
    else showToast('error', r?.error || 'Erreur');
    return r;
  },

  async createPost(locationId, data) {
    const r = await apiFetch('/api/google/posts', {
      method: 'POST', body: JSON.stringify({ locationId, ...data })
    });
    if (r?.ok) showToast('info', 'Post sauvegardé — publication Google requiert connexion GBP active');
    else showToast('error', r?.error || 'Erreur de publication');
    return r;
  },
};

// ═══════════════════════════════════════════════════════════════════════════════
// FP GA4 API — Real GA4 data client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_GA4_API = (function() {
  let _realtimeTimer = null;

  async function _loadGA4Data(propertyId) {
    try {
      const [ov, traffic, pages, audience, funnels] = await Promise.all([
        apiFetch(`/api/ga4/overview?propertyId=${encodeURIComponent(propertyId)}&days=30`).catch(() => null),
        apiFetch(`/api/ga4/traffic-sources?propertyId=${encodeURIComponent(propertyId)}&days=30`).catch(() => null),
        apiFetch(`/api/ga4/top-pages?propertyId=${encodeURIComponent(propertyId)}&days=30`).catch(() => null),
        apiFetch(`/api/ga4/audience?propertyId=${encodeURIComponent(propertyId)}&days=30`).catch(() => null),
        apiFetch(`/api/ga4/funnel?propertyId=${encodeURIComponent(propertyId)}&days=30`).catch(() => null),
      ]);
      STATE.ga4 = {
        ...(STATE.ga4 || {}),
        overview: ov,
        traffic: traffic,
        pages: pages,
        audience: audience,
        funnels: funnels,
      };
    } catch(e) { console.warn('[FP_GA4_API] data load error:', e); }
  }

  return {
    async load() {
      try {
        const status = await apiFetch('/api/ga4/status').catch(() => null);
        if (!status?.connected) {
          window.FP_DATA = window.FP_DATA || {};
          window.FP_DATA.ga4 = { connected: false };
          return;
        }
        window.FP_DATA = window.FP_DATA || {};
        window.FP_DATA.ga4 = {
          connected: true,
          propertyId: status.propertyId || null,
          propertyName: status.propertyName || status.propertyId || '',
          email: status.email || '',
        };
        STATE.ga4 = STATE.ga4 || {};
        if (status.propertyId) {
          await _loadGA4Data(status.propertyId);
        }
      } catch(e) {
        console.warn('[FP_GA4_API] load error:', e);
        window.FP_DATA = window.FP_DATA || {};
        window.FP_DATA.ga4 = { connected: false };
      }
    },

    async connectGoogle() {
      try {
        const d = await apiFetch('/api/auth/google/login');
        if (d?.url) window.location.href = d.url;
        else showToast('error', 'Google OAuth non configuré — vérifiez les variables d\'environnement');
      } catch(e) { showToast('error', 'Impossible de démarrer Google OAuth'); }
    },

    async loadProperties() {
      try {
        const r = await apiFetch('/api/ga4/properties');
        return r?.properties || [];
      } catch(e) { return []; }
    },

    async selectProperty(propertyId) {
      try {
        const r = await apiFetch('/api/ga4/property', {
          method: 'POST',
          body: JSON.stringify({ propertyId }),
        });
        if (r?.ok) {
          window.FP_DATA = window.FP_DATA || {};
          window.FP_DATA.ga4 = { ...window.FP_DATA.ga4, propertyId, connected: true };
          await _loadGA4Data(propertyId);
          render();
          showToast('success', `Propriété GA4 sélectionnée`);
        } else {
          showToast('error', r?.error || 'Erreur lors de la sélection de propriété');
        }
      } catch(e) { showToast('error', String(e)); }
    },

    async reload() {
      const pid = window.FP_DATA?.ga4?.propertyId;
      if (pid) await _loadGA4Data(pid);
      render();
    },

    async refreshRealtime() {
      const pid = window.FP_DATA?.ga4?.propertyId;
      if (!pid) return;
      try {
        const r = await apiFetch(`/api/ga4/realtime?propertyId=${encodeURIComponent(pid)}`);
        STATE.ga4 = { ...(STATE.ga4||{}), realtime: r };
        render();
      } catch(e) { console.warn('[GA4] realtime error:', e); }
    },

    setRealtimeInterval(ms) {
      if (_realtimeTimer) clearInterval(_realtimeTimer);
      if (ms > 0) _realtimeTimer = setInterval(() => this.refreshRealtime(), ms);
    },

    async export() {
      showToast('info', 'Export GA4 en cours…');
      try {
        const pid = window.FP_DATA?.ga4?.propertyId;
        if (!pid) { showToast('error', 'Sélectionnez une propriété GA4 d\'abord'); return; }
        const r = await apiFetch(`/api/ga4/export?propertyId=${encodeURIComponent(pid)}&days=30`);
        if (r?.ok && r.data) {
          const blob = new Blob([JSON.stringify(r.data, null, 2)], { type: 'application/json' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = `ga4-export-${new Date().toISOString().split('T')[0]}.json`;
          a.click();
          showToast('success', 'Export GA4 téléchargé');
        }
      } catch(e) { showToast('error', String(e)); }
    },
  };
})();

// ═══════════════════════════════════════════════════════════════════════════════
// FP GSC API — Real Search Console data client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_GSC_API = {
  async load() {
    try {
      const status = await apiFetch('/api/gsc/status').catch(() => null);
      if (!status?.connected) {
        STATE.gsc = { connected: false };
        return;
      }
      STATE.gsc = {
        connected: true,
        siteUrl: status.siteUrl || '',
        siteDisplayName: status.siteDisplayName || '',
        lastSync: status.lastSync,
        clicksTotal: status.clicksTotal || 0,
        impressionsTotal: status.impressionsTotal || 0,
        avgCTR: status.avgCTR || 0,
        avgPosition: status.avgPosition || 0,
        keywords: [],
        pages: [],
        timeSeries: [],
      };
      const siteUrl = status.siteUrl;
      if (siteUrl) {
        const [kwData, pgData, tsData] = await Promise.all([
          apiFetch(`/api/gsc/keywords?days=30`).catch(() => null),
          apiFetch(`/api/gsc/pages?days=30`).catch(() => null),
          apiFetch(`/api/gsc/impressions?days=90`).catch(() => null),
        ]);
        if (kwData?.ok) STATE.gsc.keywords = kwData.keywords || [];
        if (pgData?.ok) STATE.gsc.pages = pgData.pages || [];
        if (tsData?.ok) STATE.gsc.timeSeries = tsData.timeSeries || [];
      }
    } catch(e) {
      console.warn('[FP_GSC_API] load error:', e);
      STATE.gsc = { connected: false };
    }
  },

  async sync() {
    showToast('info', 'Synchronisation GSC en cours…');
    try {
      const r = await apiFetch('/api/gsc/sync', { method: 'POST' });
      if (r?.ok) {
        showToast('success', `GSC synchronisé — ${r.keywordsCount||0} mots-clés, ${r.pagesCount||0} pages`);
        await this.load();
        render();
      } else {
        showToast('error', r?.error || 'Sync GSC échouée');
      }
    } catch(e) { showToast('error', String(e)); }
  },

  async selectSite(siteUrl, displayName) {
    try {
      const r = await apiFetch('/api/gsc/site', {
        method: 'POST',
        body: JSON.stringify({ siteUrl, displayName }),
      });
      if (r?.ok) {
        showToast('success', `Site GSC sélectionné : ${siteUrl}`);
        STATE._gscLoaded = false;
        await this.load();
        render();
      } else {
        showToast('error', r?.error || 'Erreur');
      }
    } catch(e) { showToast('error', String(e)); }
  },

  async disconnect() {
    try {
      await apiFetch('/api/gsc/disconnect', { method: 'POST' });
      STATE.gsc = { connected: false };
      STATE._gscLoaded = false;
      showToast('success', 'Search Console déconnecté');
    } catch(e) { showToast('error', String(e)); }
  },

  async openConnect() {
    try {
      const d = await apiFetch('/api/auth/google/login');
      if (d?.url) {
        showToast('info', 'Redirection vers Google OAuth…');
        window.location.href = d.url;
      } else {
        showToast('error', 'Google OAuth non configuré');
      }
    } catch(e) { showToast('error', 'Impossible de démarrer Google OAuth'); }
  },
};

