// ═══════════════════════════════════════════════════════════════════════════════
// FP BEHAVIORAL API — Real behavioral analytics client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_BEHAVIORAL_API = {
  async load(siteUrl) {
    try {
      const url = siteUrl ? `/api/behavioral/insights?siteUrl=${encodeURIComponent(siteUrl)}` : '/api/behavioral/insights';
      const data = await apiFetch(url).catch(() => null);
      if (!data) return;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.behavioral = {
        sessionStats:  data.sessionStats  || data.stats  || null,
        insights:      data.insights      || [],
        sessions:      data.sessions      || [],
        totalSessions: data.totalSessions || data.sessionCount || 0,
        avgEngagement: data.avgEngagement || 0,
        topPages:      data.topPages      || [],
      };
      // Also load snippet status (non-blocking)
      this.loadStatus(siteUrl).catch(() => {});
    } catch(e) { console.warn('[FP_BEHAVIORAL_API] load error:', e); }
  },

  async loadStatus(siteUrl) {
    try {
      const url = siteUrl ? `/api/behavioral/status?siteUrl=${encodeURIComponent(siteUrl)}` : '/api/behavioral/status';
      const s = await apiFetch(url).catch(() => null);
      if (!s) return;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.behavioral = window.FP_DATA.behavioral || {};
      window.FP_DATA.behavioral.snippetInstalled = s.installed ?? false;
      window.FP_DATA.behavioral.snippetTotalEvents = s.totalEvents ?? 0;
      window.FP_DATA.behavioral.snippetLastEventAt = s.lastEventAt ?? null;
      window.FP_DATA.behavioral.snippetStatus = s.status ?? 'snippet_not_installed';
    } catch(e) { console.warn('[FP_BEHAVIORAL_API] loadStatus error:', e); }
  },

  async getSnippet(siteUrl) {
    if (!siteUrl) { showToast('error', 'siteUrl requis'); return null; }
    try {
      const data = await apiFetch(`/api/behavioral/snippet?siteUrl=${encodeURIComponent(siteUrl)}`);
      return data;
    } catch(e) { showToast('error', String(e)); return null; }
  },

  async generateInsights(siteUrl) {
    if (!siteUrl) { showToast('error', 'siteUrl requis'); return; }
    showToast('info', 'Génération des insights comportementaux…');
    try {
      const r = await apiFetch('/api/behavioral/generate-insights', { method: 'POST', body: JSON.stringify({ siteUrl }) });
      if (r?.ok) { await this.load(siteUrl); render(); showToast('success', 'Insights comportementaux générés'); }
      else showToast('error', r?.error || 'Erreur');
    } catch(e) { showToast('error', String(e)); }
  },
};

